# Extension categories
EXT_CATEGORIES = {
    "Raster":       [".tif", ".tiff", ".img", ".vrt", ".asc", ".nc"],
    "Vector":       [".shp", ".shx", ".dbf", ".prj", ".cpg", ".geojson", ".kml", ".gpkg"],
    "Tabular":      [".xlsx", ".xls", ".csv", ".txt", ".tsv"],
    "Script_Code":  [".py", ".r", ".js", ".ipynb", ".m"],
    "Document":     [".pdf", ".docx", ".doc", ".pptx"],
    "Image":        [".png", ".jpg", ".jpeg", ".bmp", ".gif"],
    "Archive":      [".zip", ".rar", ".7z", ".tar", ".gz"],
    "Other":        [],
}

def categorize_extension(ext):
    ext = ext.lower()
    for cat, exts in EXT_CATEGORIES.items():
        if ext in exts:
            return cat
    return "Other"

def human_size(num_bytes):
    """Convert a size in bytes to a human-readable string."""
    for unit in ["B", "KB", "MB", "GB", "TB"]:
        if abs(num_bytes) < 1024.0:
            return f"{num_bytes:,.2f} {unit}"
        num_bytes /= 1024.0
    return f"{num_bytes:.2f} PB"

def scan_folder(folder_path, folder_label):
    """Scan a folder and return a list of files with full information."""
    folder_path = Path(folder_path)
    results = {
        "folder_label": folder_label,
        "folder_path": str(folder_path),
        "exists": folder_path.exists(),
        "files": [],
        "subfolders": [],
        "summary": defaultdict(lambda: {"count": 0, "total_size": 0}),
    }
    if not folder_path.exists():
        return results

    # Recursive scan
    for root, dirs, files in os.walk(folder_path):
        root_path = Path(root)
        rel_root = root_path.relative_to(folder_path)
        if str(rel_root) != ".":
            results["subfolders"].append(str(rel_root))

        for f in files:
            fpath = root_path / f
            try:
                size = fpath.stat().st_size
            except Exception:
                size = 0
            ext = fpath.suffix.lower()
            cat = categorize_extension(ext)
            results["files"].append({
                "name": f,
                "relative_path": str(fpath.relative_to(folder_path)),
                "full_path": str(fpath),
                "extension": ext,
                "category": cat,
                "size_bytes": size,
                "size_human": human_size(size),
                "parent_folder": str(rel_root) if str(rel_root) != "." else ".",
            })
            results["summary"][cat]["count"] += 1
            results["summary"][cat]["total_size"] += size

    results["summary"] = dict(results["summary"])
    return results

def scan_excel_file(file_path, label):
    """Scan an Excel file and return sheet names and columns."""
    info = {
        "label": label,
        "path": str(file_path),
        "exists": Path(file_path).exists(),
        "sheets": [],
        "error": None,
    }
    if not info["exists"]:
        return info
    try:
        import pandas as pd
        xls = pd.ExcelFile(file_path)
        for sheet in xls.sheet_names:
            try:
                df = pd.read_excel(file_path, sheet_name=sheet, nrows=5)
                info["sheets"].append({
                    "name": sheet,
                    "n_preview_rows": len(df),
                    "columns": list(df.columns.astype(str)),
                })
            except Exception as e:
                info["sheets"].append({"name": sheet, "error": str(e)})
    except Exception as e:
        info["error"] = str(e)
    return info

