def build_missing_checklist(all_raster_names):
    """Compare expected indicators with what is actually present."""
    found = set()
    for name in all_raster_names:
        stem = Path(name).stem
        found.add(stem)

    missing = []
    present = []
    for expected, cat in EXPECTED_INDICATORS.items():
        if expected in found:
            present.append((expected, cat))
        else:
            missing.append((expected, cat))
    return present, missing, found

