# ============================================================
# SECTION 1.4: FOLDER SCANNING FUNCTIONS (INSTEAD OF JSON)
# ============================================================

EXT_CATEGORIES = {
    "Raster":  [".tif", ".tiff", ".img", ".vrt", ".asc", ".nc"],
    "Vector":  [".shp", ".shx", ".dbf", ".prj", ".cpg", ".geojson"],
    "Tabular": [".xlsx", ".xls", ".csv", ".txt"],
    "Image":   [".png", ".jpg", ".jpeg"],
    "Other":   [],
}

def categorize(ext):
    ext = ext.lower()
    for cat, exts in EXT_CATEGORIES.items():
        if ext in exts:
            return cat
    return "Other"

def scan_folder(folder_path):
    folder = Path(folder_path)
    files = []
    if not folder.exists():
        return files
    for root, dirs, fnames in os.walk(folder):
        for f in fnames:
            fpath = Path(root) / f
            try:
                size = fpath.stat().st_size
            except Exception:
                size = 0
            files.append({
                "name": f,
                "full_path": str(fpath),
                "stem": fpath.stem,
                "extension": fpath.suffix.lower(),
                "category": categorize(fpath.suffix),
                "size_bytes": size,
            })
    return files

def create_output_structure(out_root, subfolders):
    out_root = Path(out_root)
    out_root.mkdir(parents=True, exist_ok=True)
    for sub in subfolders:
        (out_root / sub).mkdir(parents=True, exist_ok=True)

def clean_col(s):
    return str(s).strip().replace('\u00a0', ' ').replace('\u200c', '').strip()

def read_first_sheet(file_path, nrows=5):
    p = str(file_path)
    if not os.path.exists(p):
        raise FileNotFoundError(f"File not found: {p}")
    ext = p.lower().rsplit('.', 1)[-1] if '.' in p else ''
    if ext == 'csv':
        return pd.read_csv(p, nrows=nrows, low_memory=False)
    if ext in ('xlsx', 'xls'):
        xls = pd.ExcelFile(p)
        return pd.read_excel(p, sheet_name=xls.sheet_names[0], nrows=nrows)
    try:
        xls = pd.ExcelFile(p)
        return pd.read_excel(p, sheet_name=xls.sheet_names[0], nrows=nrows)
    except Exception:
        return pd.read_csv(p, nrows=nrows, low_memory=False)

def detect_columns(file_path, candidates_dict):
    result = {}
    status = "OK"
    if not os.path.exists(file_path):
        return {role: {"primary": None, "all_available": [], "missing": True}
                for role in candidates_dict}, "FILE_NOT_FOUND"
    try:
        df = read_first_sheet(file_path, nrows=5)
        available = set(clean_col(c) for c in df.columns)
        for role, cands in candidates_dict.items():
            cleaned = [clean_col(c) for c in cands]
            found = [c for c in cleaned if c in available]
            result[role] = {
                "primary": found[0] if found else None,
                "all_available": found,
                "missing": not bool(found),
            }
    except Exception as e:
        status = f"ERROR: {e}"
        for role in candidates_dict:
            result[role] = {"primary": None, "all_available": [], "missing": True}
    return result, status

def inspect_expert_file(file_path):
    """Inspect expert_ahp.xlsx."""
    info = {"path": str(file_path), "exists": os.path.exists(file_path),
            "sheets": [], "error": None}
    if not info["exists"]:
        return info
    try:
        xls = pd.ExcelFile(file_path)
        for sheet in xls.sheet_names[:10]:
            try:
                df = pd.read_excel(file_path, sheet_name=sheet, nrows=10)
                info["sheets"].append({
                    "name": sheet,
                    "n_columns": len(df.columns),
                    "columns": [clean_col(c) for c in df.columns],
                })
            except Exception as e:
                info["sheets"].append({"name": sheet, "error": str(e)})
    except Exception as e:
        info["error"] = str(e)
    return info

def compute_effective_idw_resolution(basin_area_km2, n_stations):
    if n_stations <= 0:
        return None
    area_m2 = float(basin_area_km2) * 1e6
    eff_m = float(2 * np.sqrt(area_m2 / (np.pi * float(n_stations))))
    return round(eff_m, 1)

