def main():
    start = time.time()
    print("\n" + "=" * 70)
    print(" PART 1: SELF-CONTAINED CONFIGURATION")
    print("=" * 70)

    # --- 0. Output folders ---
    print("\n[0/7] Creating output folder structure...")
    create_output_structure(OUT, OUT_SUBFOLDERS)
    for sub in OUT_SUBFOLDERS:
        print(f"      ✓ {os.path.join(OUT, sub)}")

    logs_dir = Path(OUT) / "logs"
    config_dir = Path(OUT) / "config"

    # --- 1. Direct folder scan (no JSON) ---
    print("\n[1/7] Scanning input folders (no JSON dependency)...")
    all_files = []
    for label, folder in INPUT_FOLDERS.items():
        files = scan_folder(folder)
        for f in files:
            f["source_folder"] = label
        all_files.extend(files)
        print(f"      {label}: {len(files)} files")

    total_files = len(all_files)
    raster_files = [f for f in all_files if f["category"] == "Raster"]
    print(f"      Total files: {total_files}")
    print(f"      Raster files: {len(raster_files)}")

    # --- 2. Indicator mapping ---
    print("\n[2/7] Building indicator path map...")
    priority_order = ["extract_by_mask", "agp", "gee", "arcmap"]
    path_map = {}
    not_found = []

    for real_name, std_name in INDICATOR_NAME_MAP.items():
        found = None
        for label in priority_order:
            for f in raster_files:
                if f["source_folder"] == label and f["stem"] == real_name:
                    found = f
                    break
            if found:
                break
        if found:
            path_map[std_name] = {
                "standard_name": std_name,
                "real_filename": found["name"],
                "full_path": found["full_path"],
                "source_folder": found["source_folder"],
            }
        else:
            not_found.append((std_name, real_name))

    print(f"      ✓ Mapped: {len(path_map)}")
    if not_found:
        print(f"      ⚠️ Not found: {len(not_found)}")

    # --- 3. Inspect expert AHP file ---
    print("\n[3/7] Inspecting expert AHP file...")
    expert_info = inspect_expert_file(EXPERT_AHP_FILE)
    print(f"      Exists: {expert_info['exists']}")
    if expert_info['exists']:
        print(f"      Sheets: {[s['name'] for s in expert_info['sheets']]}")

    # --- 4. Dynamic column detection ---
    print("\n[4/7] Detecting point file columns...")

    wells_cols, wells_status = detect_columns(
        POINT_EXCEL_FILES["wells"], WELLS_COLUMN_CANDIDATES
    )
    n_wells = sum(1 for v in wells_cols.values() if not v["missing"])
    print(f"      wells: {wells_status} | {n_wells}/{len(wells_cols)} roles found")

    qanats_cols, qanats_status = detect_columns(
        POINT_EXCEL_FILES["qanats"], QANATS_COLUMN_CANDIDATES
    )
    n_qanats = sum(1 for v in qanats_cols.values() if not v["missing"])
    print(f"      qanats: {qanats_status} | {n_qanats}/{len(qanats_cols)} roles found")

    wq_cols, wq_status = detect_columns(
        POINT_EXCEL_FILES["water_quality"], WQ_COLUMN_CANDIDATES
    )
    n_wq = sum(1 for v in wq_cols.values() if not v["missing"])
    print(f"      water_quality: {wq_status} | {n_wq}/{len(wq_cols)} roles found")

    # --- 5. Effective IDW resolution ---
    print("\n[5/7] Computing effective IDW resolutions...")
    basin_area_km2 = 31450.0
    n_gw = 22
    n_sw = 18
    n_total = n_gw + n_sw

    eff_gw = compute_effective_idw_resolution(basin_area_km2, n_gw)
    eff_sw = compute_effective_idw_resolution(basin_area_km2, n_sw)
    eff_total = compute_effective_idw_resolution(basin_area_km2, n_total)

    effective_resolutions = {
        "groundwater_m": eff_gw,
        "groundwater_km": round(float(eff_gw) / 1000.0, 2) if eff_gw else None,
        "surface_water_m": eff_sw,
        "surface_water_km": round(float(eff_sw) / 1000.0, 2) if eff_sw else None,
        "combined_m": eff_total,
        "combined_km": round(float(eff_total) / 1000.0, 2) if eff_total else None,
        "basin_area_km2": basin_area_km2,
        "n_groundwater_stations": n_gw,
        "n_surface_stations": n_sw,
        "formula": "effective_res = 2 * sqrt(area / (pi * n_stations))",
    }
    print(f"      GW: {eff_gw} m | SW: {eff_sw} m | Combined: {eff_total} m")

    # --- 6. Build final_config.json ---
    print("\n[6/7] Building final_config.json...")
