    w(" PART 1 CONFIG REPORT (Self-Contained)")
    w(" Watershed Health Resilience Index (WHRI)")
    w("=" * 78)
    w(f" Generated: {datetime.datetime.now().strftime('%Y-%m-%d %H:%M:%S')}")
