# ============================================================
# PART 2: DATA LOADER
# Watershed Health Resilience Index (WHRI)
# ============================================================
# This version includes:
#   - CRS-aware sampling (resolves mismatch between EPSG:4326 and EPSG:32639)
#   - Nearest-valid-pixel fallback for 5 indicators with extensive NaN
#   - FAHP markdown parser (Sheet2 is stored as a markdown table)
#   - Automatic selection of the best year column (sals/sal_hafr)
#   - Use of Omgh_s as the water level column
# ============================================================

import os
import json
import pickle
import datetime
import numpy as np
import pandas as pd
import rasterio
from rasterio.warp import transform as rio_transform
from rasterio.windows import Window

# ============================================================
# SECTION 1: Config and paths
# ============================================================

COLUMN_OVERRIDES = {"water_level": "Omgh_s", "well_depth": "omgh_chah"}
YEAR_CANDIDATES = ["sal_hafr", "sal", "sals", "YY", "sal_amar"]

# Default base directory (user's Desktop)
DEFAULT_BASE = Path.home() / "Desktop"

# Config file produced by Part 1
CONFIG_PATH = str(DEFAULT_BASE / "WHRI_output" / "config" / "final_config.json")

with open(CONFIG_PATH, "r", encoding="utf-8") as f:
    CFG = json.load(f)

OUT = CFG["paths"]["output_root"]
INTERMEDIATE = os.path.join(OUT, "intermediate")
LOGS = os.path.join(OUT, "logs")
os.makedirs(INTERMEDIATE, exist_ok=True)
os.makedirs(LOGS, exist_ok=True)

RANDOM_SEED = CFG["analysis_params"]["output"]["random_seed"]
np.random.seed(RANDOM_SEED)

print("\n" + "=" * 70)
print(" PART 2: DATA LOADER")
print("=" * 70)

# ============================================================
# SECTION 2: Helper functions
# ============================================================

def clean_col(s):
    return str(s).strip().replace('\u00a0', ' ').replace('\u200c', '').strip()

def load_raster_metadata(path):
    with rasterio.open(path) as src:
        return {
            "path": path,
            "width": src.width, "height": src.height,
            "crs": str(src.crs),
            "bounds": (float(src.bounds.left), float(src.bounds.bottom),
                       float(src.bounds.right), float(src.bounds.top)),
            "nodata": src.nodata,
        }

def sample_points_crs_aware(raster_path, coords_utm39n, source_crs="EPSG:32639",
                             search_radius=0):
    """CRS-aware sampling with fallback to the nearest valid pixel."""
    with rasterio.open(raster_path) as src:
        raster_crs = src.crs
        if raster_crs is None:
            return np.full(len(coords_utm39n), np.nan)

        # Coordinate transformation
        if str(raster_crs).upper() == str(source_crs).upper():
            coords_use = coords_utm39n
        else:
            xs, ys = zip(*coords_utm39n)
            try:
                xs_new, ys_new = rio_transform(source_crs, raster_crs, xs, ys)
                coords_use = list(zip(xs_new, ys_new))
            except Exception:
                return np.full(len(coords_utm39n), np.nan)

        values = []
        for coord in coords_use:
            try:
                row, col = src.index(coord[0], coord[1])
                v = src.read(1, window=Window(col, row, 1, 1))
                val = float(v[0, 0])
                is_nodata = (src.nodata is not None and val == src.nodata) or np.isnan(val)

                if not is_nodata:
                    values.append(val)
                    continue

                # Search for the nearest valid pixel
                if search_radius <= 0:
                    values.append(np.nan)
                    continue

                r = search_radius
                win = Window(col - r, row - r, 2*r + 1, 2*r + 1)
                try:
                    block = src.read(1, window=win)
                except Exception:
                    values.append(np.nan)
                    continue

                if src.nodata is not None:
                    block = np.where(block == src.nodata, np.nan, block)
                block = block.astype(float)

                if np.all(np.isnan(block)):
                    values.append(np.nan)
                    continue

                # Nearest
                cy, cx = r, r
                ys_idx, xs_idx = np.indices(block.shape)
                dist = (ys_idx - cy)**2 + (xs_idx - cx)**2
                dist = np.where(np.isnan(block), np.inf, dist)
                min_idx = np.unravel_index(np.argmin(dist), dist.shape)
                values.append(float(block[min_idx]))

            except Exception:
                values.append(np.nan)

    return np.array(values)

def find_column_in_df(df, candidate_names):
    cleaned_cols = {clean_col(c): c for c in df.columns}
    for cand in candidate_names:
        if cand is None:
            continue
        cc = clean_col(cand)
        if cc in cleaned_cols:
            return cleaned_cols[cc]
    return None

def pick_best_year_column(df, candidates):
    best_col, best_count = None, 0
    for cand in candidates:
        col = find_column_in_df(df, [cand])
        if col is None:
            continue
        yr = pd.to_numeric(df[col], errors="coerce")
        valid = ((yr >= 1300) & (yr <= 1500)) | ((yr >= 1900) & (yr <= 2200))
        n = valid.sum()
        if n > best_count:
            best_count, best_col = n, col
    return best_col, best_count

def parse_md_row(text):
    """Parse a markdown table row: | a | b | c |"""
    parts = str(text).split("|")
    parts = [p.strip() for p in parts]
    if parts and parts[0] == "":
        parts = parts[1:]
    if parts and parts[-1] == "":
        parts = parts[:-1]
    return parts

def parse_fraction(s):
    """Convert '1/2' to 0.5 and '1' to 1.0."""
    s = str(s).strip()
    if "/" in s:
        a, b = s.split("/")
        return float(a.strip()) / float(b.strip())
    return float(s)

# ============================================================
# STEP 1: metadata
# ============================================================

print("\n[1/10] Reading raster metadata...")
raster_meta = {}
crs_groups = {}
for std_name, info in CFG["indicators"]["path_map"].items():
    try:
        meta = load_raster_metadata(info["full_path"])
        raster_meta[std_name] = meta
        crs_groups.setdefault(meta["crs"], []).append(std_name)
    except Exception as e:
        print(f"      ⚠️ {std_name}: {e}")

print(f"      ✓ {len(raster_meta)} rasters")
for crs, names in crs_groups.items():
    print(f"      {crs}: {len(names)} rasters")
WHRI_CRS = raster_meta["TBM_WHRI"]["crs"]

# ============================================================
# STEP 2: wells
# ============================================================

print("\n[2/10] Loading wells...")
wells_file = CFG["paths"]["point_excels"]["wells"]
wells_df = pd.read_excel(wells_file)
print(f"      ✓ Loaded: {wells_df.shape}")

wells_cols_detected = CFG["wells_columns_detected"]
actual_cols = {
    "coords_x": find_column_in_df(wells_df, [wells_cols_detected["coords_x"]["primary"]]),
    "coords_y": find_column_in_df(wells_df, [wells_cols_detected["coords_y"]["primary"]]),
    "water_level": find_column_in_df(wells_df, [COLUMN_OVERRIDES["water_level"]]),
    "well_depth": find_column_in_df(wells_df, [COLUMN_OVERRIDES["well_depth"]]),
    "identifier": find_column_in_df(wells_df, wells_cols_detected["identifier"]["all_available"]),
}
for role, col in actual_cols.items():
    print(f"      {'✓' if col else '✗'} {role:15s} = {col}")

n_initial_wells = len(wells_df)

# ============================================================
# STEP 3: extraction
# ============================================================

print("\n[3/10] Extracting columns...")
wells_subset = pd.DataFrame()
wells_subset["_well_id"] = np.arange(len(wells_df))
wells_subset["coords_x"] = pd.to_numeric(wells_df[actual_cols["coords_x"]], errors="coerce").values
wells_subset["coords_y"] = pd.to_numeric(wells_df[actual_cols["coords_y"]], errors="coerce").values
wells_subset["water_level"] = pd.to_numeric(wells_df[actual_cols["water_level"]], errors="coerce").values
if actual_cols["well_depth"]:
    wells_subset["well_depth"] = pd.to_numeric(wells_df[actual_cols["well_depth"]], errors="coerce").values

year_col, n_year = pick_best_year_column(wells_df, YEAR_CANDIDATES)
wells_subset["year_raw"] = pd.to_numeric(wells_df[year_col], errors="coerce").values if year_col else np.nan
wells_subset["identifier"] = wells_subset["_well_id"].values
print(f"      Year column: {year_col} ({n_year} valid)")

# ============================================================
# STEP 4: filtering
# ============================================================

print(f"\n[4/10] Filtering...")
print(f"      Start: {len(wells_subset)}")

wells_subset = wells_subset.dropna(subset=["coords_x", "coords_y"]).reset_index(drop=True)
wells_subset = wells_subset.dropna(subset=["water_level"]).reset_index(drop=True)
wells_subset = wells_subset[wells_subset["water_level"] > 0].reset_index(drop=True)
wells_subset = wells_subset[wells_subset["water_level"] < 500].reset_index(drop=True)
print(f"      After WL filter: {len(wells_subset)}")

bounds = raster_meta["TBM_WHRI"]["bounds"]
in_bounds = (
    (wells_subset["coords_x"] >= bounds[0]) & (wells_subset["coords_x"] <= bounds[2]) &
    (wells_subset["coords_y"] >= bounds[1]) & (wells_subset["coords_y"] <= bounds[3])
)
wells_subset = wells_subset[in_bounds].reset_index(drop=True)
print(f"      After bounds: {len(wells_subset)}")

wells_subset = wells_subset.drop_duplicates(subset=["_well_id"]).reset_index(drop=True)
wells_subset["identifier"] = wells_subset["_well_id"].values
print(f"      Final: {len(wells_subset)} wells")

if len(wells_subset) < 20:
    raise RuntimeError(f"Only {len(wells_subset)} wells remained")

# ============================================================
# STEP 5: CRS check
# ============================================================

print(f"\n[5/10] CRS check...")
x_med = np.nanmedian(wells_subset["coords_x"].values)
print(f"      X median: {x_med:.2f}")
if 0 < x_med < 180:
    from pyproj import Transformer
    t = Transformer.from_crs("EPSG:4326", "EPSG:32639", always_xy=True)
    x_u, y_u = t.transform(wells_subset["coords_x"].values, wells_subset["coords_y"].values)
    wells_subset["coords_x"] = x_u
    wells_subset["coords_y"] = y_u
    print(f"      ✓ Reprojected WGS84 → UTM 39N")
else:
    print(f"      ✓ Already UTM")

# ============================================================
# STEP 6: quadrants
# ============================================================

print(f"\n[6/10] Quadrants...")
center_x = (bounds[0] + bounds[2]) / 2
center_y = (bounds[1] + bounds[3]) / 2

def assign_quadrant(x, y):
    if x >= center_x and y >= center_y: return "NE"
    elif x < center_x and y >= center_y: return "NW"
    elif x < center_x and y < center_y: return "SW"
    else: return "SE"

wells_subset["quadrant"] = wells_subset.apply(
    lambda r: assign_quadrant(r["coords_x"], r["coords_y"]), axis=1)

for q in ["NW", "NE", "SW", "SE"]:
    print(f"      {q}: {(wells_subset['quadrant'] == q).sum()}")

# ============================================================
# STEP 7: select 20 wells
# ============================================================

print(f"\n[7/10] Selecting 20 wells...")
n_target = CFG["analysis_params"]["calibration"]["wells_selection"]["n_selected"]
min_dist = CFG["analysis_params"]["calibration"]["wells_selection"]["min_distance_between_wells_m"]

def select_wells(df, n_t, min_d, seed=42):
    if len(df) == 0:
        return pd.DataFrame(columns=df.columns)
    df_s = df.sample(frac=1, random_state=seed).reset_index(drop=True)
    selected = []
    for _, row in df_s.iterrows():
        if all(np.sqrt((row["coords_x"] - s["coords_x"])**2 +
                      (row["coords_y"] - s["coords_y"])**2) >= min_d for s in selected):
            selected.append(row.to_dict())
        if len(selected) >= n_t:
            break
    return pd.DataFrame(selected) if selected else pd.DataFrame(columns=df.columns)

n_per_q = max(3, n_target // 4 + 2)
selected_dfs = []
for q in ["NW", "NE", "SW", "SE"]:
    df_q = wells_subset[wells_subset["quadrant"] == q]
    if len(df_q) == 0:
        continue
    sel = select_wells(df_q, n_per_q, min_dist, RANDOM_SEED)
    if len(sel) > 0:
        selected_dfs.append(sel)

if selected_dfs:
    selected_wells = pd.concat(selected_dfs, ignore_index=True)
else:
    selected_wells = wells_subset.sample(n=min(n_target, len(wells_subset)),
                                          random_state=RANDOM_SEED).reset_index(drop=True).copy()

if 0 < len(selected_wells) < n_target:
    remaining = wells_subset[~wells_subset["_well_id"].isin(selected_wells["_well_id"])].copy()
    for q in ["NW", "NE", "SW", "SE"]:
        if len(selected_wells) >= n_target:
            break
        rem_q = remaining[remaining["quadrant"] == q]
        if len(rem_q) == 0:
            continue
        extra = select_wells(rem_q, n_target - len(selected_wells), min_dist // 2, RANDOM_SEED)
        if len(extra) > 0:
            selected_wells = pd.concat([selected_wells, extra], ignore_index=True)

if len(selected_wells) > n_target:
    selected_wells = selected_wells.sample(n=n_target, random_state=RANDOM_SEED).reset_index(drop=True)

selected_wells = selected_wells.reset_index(drop=True)
selected_wells["identifier"] = selected_wells["_well_id"].values

print(f"      ✓ Selected: {len(selected_wells)}")
for q in ["NW", "NE", "SW", "SE"]:
    print(f"         {q}: {(selected_wells['quadrant'] == q).sum()}")

# ============================================================
# STEP 8: sampling
# ============================================================

print(f"\n[8/10] Sampling indicators...")
coords_utm39n = list(zip(selected_wells["coords_x"].values, selected_wells["coords_y"].values))

NEAREST_VALID_INDICATORS = {
    "TBM_Subsidence_Clipped", "TBM_Subsidence_Fuzzy",
    "TBM_WHRI", "TBM_WHRI_Classified", "TBM_Management_Zones",
}
SEARCH_RADIUS = 50

indicator_samples = {}
sampling_report = {}

for std_name in CFG["indicators"]["path_map"].keys():
    if std_name not in raster_meta:
        continue
    try:
        radius = SEARCH_RADIUS if std_name in NEAREST_VALID_INDICATORS else 0
        values = sample_points_crs_aware(
            raster_meta[std_name]["path"], coords_utm39n,
            source_crs=WHRI_CRS, search_radius=radius
        )
        n_valid = int(np.sum(~np.isnan(values)))
        indicator_samples[std_name] = values
        sampling_report[std_name] = {
            "raster_crs": raster_meta[std_name]["crs"],
            "n_valid": n_valid,
            "n_total": len(values),
            "used_nearest_valid": radius > 0,
        }
    except Exception as e:
        print(f"      ⚠️ {std_name}: {e}")
        indicator_samples[std_name] = np.full(len(coords_utm39n), np.nan)

samples_df = pd.DataFrame(indicator_samples)
samples_df.insert(0, "identifier", selected_wells["identifier"].values)
samples_df.insert(1, "coords_x", selected_wells["coords_x"].values)
samples_df.insert(2, "coords_y", selected_wells["coords_y"].values)
samples_df.insert(3, "quadrant", selected_wells["quadrant"].values)
samples_df["water_level"] = selected_wells["water_level"].values
if "well_depth" in selected_wells.columns:
    samples_df["well_depth"] = selected_wells["well_depth"].values
if "year_raw" in selected_wells.columns:
    samples_df["year"] = selected_wells["year_raw"].values

tbm_cols = [c for c in samples_df.columns if c.startswith("TBM_")]
valid_counts = samples_df[tbm_cols].notna().sum()
print(f"      Samples shape: {samples_df.shape}")
print(f"      Indicators with ≥15 valid: {(valid_counts >= 15).sum()}/{len(tbm_cols)}")

# ============================================================
# STEP 9: Qanats + Water Quality
# ============================================================

print(f"\n[9/10] Qanats and WQ...")

try:
    qanats_df = pd.read_excel(CFG["paths"]["point_excels"]["qanats"])
    qanats_df.columns = [clean_col(c) for c in qanats_df.columns]
    for cx in ["UTMX_mazha", "UTMX_madar", "utmx"]:
        if cx in qanats_df.columns:
            qanats_df["coords_x"] = pd.to_numeric(qanats_df[cx], errors="coerce")
            break
    for cy in ["UTMY_mazha", "UTMY_madar", "utmy"]:
        if cy in qanats_df.columns:
            qanats_df["coords_y"] = pd.to_numeric(qanats_df[cy], errors="coerce")
            break
    for wl in ["sath_d", "sath_s", "Omgh_Q", "Omgh_d"]:
        if wl in qanats_df.columns:
            wl_vals = pd.to_numeric(qanats_df[wl], errors="coerce")
            if (wl_vals > 0).sum() > 0:
                qanats_df["water_level"] = wl_vals
                print(f"      Qanats WL column: {wl}")
                break
    qanats_df = qanats_df.dropna(subset=["coords_x", "coords_y"]).reset_index(drop=True)
    q_in = ((qanats_df["coords_x"] >= bounds[0]) & (qanats_df["coords_x"] <= bounds[2]) &
            (qanats_df["coords_y"] >= bounds[1]) & (qanats_df["coords_y"] <= bounds[3]))
    qanats_df = qanats_df[q_in].reset_index(drop=True)
    print(f"      Qanats: {len(qanats_df)}")
except Exception as e:
    print(f"      ⚠️ Qanats: {e}")
    qanats_df = pd.DataFrame()

try:
    wq_df = pd.read_excel(CFG["paths"]["point_excels"]["water_quality"])
    wq_df.columns = [clean_col(c) for c in wq_df.columns]
    if "X_UTM" in wq_df.columns:
        wq_df["coords_x"] = pd.to_numeric(wq_df["X_UTM"], errors="coerce")
    if "Y_UTM" in wq_df.columns:
        wq_df["coords_y"] = pd.to_numeric(wq_df["Y_UTM"], errors="coerce")
    wq_df = wq_df.dropna(subset=["coords_x", "coords_y"]).reset_index(drop=True)
    print(f"      Water quality: {len(wq_df)}")
except Exception as e:
    print(f"      ⚠️ WQ: {e}")
    wq_df = pd.DataFrame()

# ============================================================
# STEP 10: FAHP (Markdown table parser)
# ============================================================

print(f"\n[10/10] FAHP extraction (markdown parser)...")
fahp_matrices = {}

try:
    df2 = pd.read_excel(CFG["paths"]["expert_ahp"], sheet_name="Sheet2", header=None)
    print(f"      Sheet2 shape: {df2.shape}")

    criteria = ["NDVI", "Subsidence", "Surface WQ", "Groundwater WQ", "Well Density"]

    # Find expert markers
    expert_markers = []
    for r in range(len(df2)):
        for c in range(df2.shape[1]):
            v = df2.iloc[r, c]
            if pd.isna(v):
                continue
            cell = clean_col(v)
            if "Expert" in cell and len(cell) < 30:
                expert_markers.append((r, c, cell))

    print(f"      Found {len(expert_markers)} expert markers")

    # Extract matrix for each expert
    for start_row, col_idx, expert_name in expert_markers:
        # Look for the header (NDVI) in following rows
        header_row = None
        for j in range(start_row + 1, min(start_row + 5, len(df2))):
            v = df2.iloc[j, col_idx]
            if pd.isna(v):
                continue
            cell = clean_col(v)
            if "NDVI" in cell and "|" in cell:
                header_row = j
                break

        if header_row is None:
            print(f"      ⚠️ {expert_name}: header not found")
            continue

        # Data starts at header_row + 2 (header + separator + 5 data rows)
        matrix_rows = []
        for k in range(header_row + 2, header_row + 2 + 5):
            if k >= len(df2):
                break
            v = df2.iloc[k, col_idx]
            if pd.isna(v):
                break
            cell = clean_col(v)
            if "|" not in cell:
                break
            parts = parse_md_row(cell)
            if len(parts) < 6:
                continue
            try:
                row_vals = [parse_fraction(p) for p in parts[1:6]]
                matrix_rows.append(row_vals)
            except Exception as e:
                print(f"      ⚠️ {expert_name}: parse error at row {k}: {e}")

        if len(matrix_rows) == 5:
            matrix = np.array(matrix_rows)
            fahp_matrices[expert_name] = {
                "matrix": matrix.tolist(),
                "criteria": criteria,
            }
            row_sums = matrix.sum(axis=1)
            print(f"      ✓ {expert_name}: extracted (row sums: {[round(s,2) for s in row_sums]})")
        else:
            print(f"      ⚠️ {expert_name}: only {len(matrix_rows)} rows parsed")

    print(f"\n      Total FAHP matrices: {len(fahp_matrices)}")

    if len(fahp_matrices) == 0:
        print(f"\n      *** RAW DUMP of first 15 rows ***")
        for r in range(0, min(15, len(df2))):
            v = df2.iloc[r, 1]
            if not pd.isna(v):
                print(f"      Row {r}: {repr(str(v)[:200])}")

except Exception as e:
    print(f"      ⚠️ FAHP: {e}")
    import traceback
    traceback.print_exc()

# ============================================================
# Save
# ============================================================

print(f"\n[Final] Saving...")

wells_subset.to_csv(os.path.join(INTERMEDIATE, "wells_filtered.csv"),
                   index=False, encoding="utf-8-sig")
print(f"      ✓ wells_filtered.csv ({len(wells_subset)})")

selected_wells.to_csv(os.path.join(INTERMEDIATE, "wells_selected.csv"),
                     index=False, encoding="utf-8-sig")
