def sample_stats(raster_path, n_samples=30000, n_windows=20, window_size=1024):
    """Sample raster statistics from random windows"""
    rng = np.random.default_rng(42)
    with rasterio.open(raster_path) as src:
        H, W = src.height, src.width
        nodata = src.nodata
        samples = []
        total = 0
        for _ in range(n_windows):
            if total >= n_samples * 1.5:
                break
            r = rng.integers(0, max(1, H - window_size))
            c = rng.integers(0, max(1, W - window_size))
            w = Window(c, r, min(window_size, W - c), min(window_size, H - r))
            block = src.read(1, window=w).astype(np.float32)
            if nodata is not None:
                block = np.where(block == nodata, np.nan, block)
            block = block[np.isfinite(block)]
            if len(block) > 0:
                n_take = min(3000, len(block))
                idx = rng.choice(len(block), n_take, replace=False)
                samples.append(block[idx])
                total += n_take
    if not samples:
        return None
    vals = np.concatenate(samples)
    if len(vals) > n_samples:
        idx = rng.choice(len(vals), n_samples, replace=False)
        vals = vals[idx]
    return {
        "min": float(vals.min()),
        "max": float(vals.max()),
        "mean": float(vals.mean()),
        "median": float(np.median(vals)),
        "p1": float(np.percentile(vals, 1)),
        "p5": float(np.percentile(vals, 5)),
        "p95": float(np.percentile(vals, 95)),
        "p99": float(np.percentile(vals, 99)),
        "range": float(vals.max() - vals.min()),
        "skewness": float(calc_skew(vals)),
    }

def build_fuzzy_blockwise(src_path, dst_path, direction, method, beta, gamma, offset):
    """Build fuzzy raster block-by-block (memory-safe)"""
    with rasterio.open(src_path) as src:
        profile = src.profile.copy()
        profile.update(dtype='float32', compress='lzw', nodata=SAFE_NODATA,
                       tiled=True, blockxsize=512, blockysize=512)
        nodata = src.nodata
        with rasterio.open(dst_path, 'w', **profile) as dst:
            for ji, window in src.block_windows(1):
                block = src.read(1, window=window).astype(np.float32)
                mask = np.ones(block.shape, dtype=bool)
                if nodata is not None:
                    mask &= (block != nodata)
                mask &= np.isfinite(block)

                block_shifted = block + offset
                if method == "log":
                    if direction == "large":
                        result = sigmoid_large_log(block_shifted, beta, gamma)
                    else:
                        result = sigmoid_small_log(block_shifted, beta, gamma)
                else:
                    if direction == "large":
                        result = sigmoid_large_linear(block_shifted, beta, gamma)
                    else:
                        result = sigmoid_small_linear(block_shifted, beta, gamma)

                result = np.clip(result, 0.0, 1.0)
                result = np.where(mask, result, SAFE_NODATA).astype(np.float32)
                dst.write(result, 1, window=window)

def build_composite_blockwise(src_paths, dst_path, weights=None):
    """Build composite raster (mean of multiple rasters) block-by-block"""
    if weights is None:
        weights = [1.0 / len(src_paths)] * len(src_paths)
    with rasterio.open(src_paths[0]) as src_ref:
        profile = src_ref.profile.copy()
        profile.update(dtype='float32', compress='lzw', nodata=SAFE_NODATA,
                       tiled=True, blockxsize=512, blockysize=512)
        srcs = [rasterio.open(p) for p in src_paths]
        with rasterio.open(dst_path, 'w', **profile) as dst:
            for ji, window in src_ref.block_windows(1):
                wsum = np.zeros((window.height, window.width), dtype=np.float32)
                wgt = np.zeros((window.height, window.width), dtype=np.float32)
                for src, w in zip(srcs, weights):
                    b = src.read(1, window=window).astype(np.float32)
                    nd = src.nodata
                    valid = np.isfinite(b)
                    if nd is not None:
                        valid &= (b != nd)
                    # Also exclude SAFE_NODATA explicitly
                    valid &= (b != SAFE_NODATA)
                    wsum += np.where(valid, w * b, 0.0).astype(np.float32)
                    wgt += np.where(valid, w, 0.0).astype(np.float32)
                result = np.where(wgt > 0, wsum / (wgt + 1e-10), SAFE_NODATA).astype(np.float32)
                dst.write(result, 1, window=window)
        for src in srcs:
            src.close()

def sample_nearest_valid(raster_path, coords, max_radius_px=200):
    """
    Sample raster at coordinates with nearest-valid fallback.
    Returns NaN for pixels that cannot be sampled.
    Converts SAFE_NODATA (-9999) to NaN.
    """
    values = []
    with rasterio.open(raster_path) as src:
        nodata = src.nodata
        for x, y in coords:
            try:
                v = next(src.sample([(x, y)]))[0]
                # Handle both declared nodata and SAFE_NODATA
                if nodata is not None and v == nodata:
                    v = np.nan
                if v == SAFE_NODATA:
                    v = np.nan
                if np.isfinite(v):
                    values.append(float(v))
                    continue

                row, col = src.index(x, y)
                found = False
                for r in [5, 10, 20, 50, 100, max_radius_px]:
                    if r > max_radius_px:
                        break
                    w = Window(col - r, row - r, 2 * r + 1, 2 * r + 1)
                    try:
                        block = src.read(1, window=w)
                    except Exception:
                        break
                    if nodata is not None:
                        block = np.where(block == nodata, np.nan, block)
                    block = np.where(block == SAFE_NODATA, np.nan, block)
                    valid = np.isfinite(block)
                    if valid.any():
                        cy = min(r, block.shape[0] - 1)
                        cx = min(r, block.shape[1] - 1)
                        ys, xs = np.where(valid)
                        dist = (ys - cy) ** 2 + (xs - cx) ** 2
                        idx = np.argmin(dist)
                        values.append(float(block[ys[idx], xs[idx]]))
                        found = True
                        break
                if not found:
                    values.append(np.nan)
            except Exception:
                values.append(np.nan)
    return np.array(values)

