def copy_binary_as_fuzzy(src, dst):
    """Copy binary mask as fuzzy raster (values already 0/1)"""
    if not os.path.exists(src):
        return False
    with rasterio.open(src) as s:
        profile = s.profile.copy()
        profile.update(dtype='float32', compress='lzw', nodata=SAFE_NODATA,
                       tiled=True, blockxsize=512, blockysize=512)
        with rasterio.open(dst, 'w', **profile) as d:
            for ji, window in s.block_windows(1):
                block = s.read(1, window=window).astype(np.float32)
                nd = s.nodata
                if nd is not None:
                    block = np.where(block == nd, np.nan, block)
                block = np.clip(block, 0.0, 1.0)
                block = np.where(np.isfinite(block), block, SAFE_NODATA)
                d.write(block.astype(np.float32), 1, window=window)
    return True

