# ---- Triangular Fuzzy Numbers ----
def crisp_to_tfn(a):
    """Convert Saaty crisp (1-9 or 1/9-1) to TFN (l, m, u)."""
    try:
        a = float(a)
    except Exception:
        a = 1.0
    if a <= 0:
        a = 1.0
    if abs(a - 1.0) < 1e-9:
        return (1.0, 1.0, 1.0)
    if a > 1:
        return (max(1.0, a - 1.0), a, min(9.0, a + 1.0))
    inv = 1.0 / a
    return (1.0 / min(9.0, inv + 1.0), 1.0 / inv, 1.0 / max(1.0, inv - 1.0))

def fmul(t1, t2):
    return (t1[0] * t2[0], t1[1] * t2[1], t1[2] * t2[2])

def fpow(t, p):
    return (t[0] ** p, t[1] ** p, t[2] ** p)

def fadd(t1, t2):
    return (t1[0] + t2[0], t1[1] + t2[1], t1[2] + t2[2])

def frec(t):
    return (1.0 / t[2], 1.0 / t[1], 1.0 / t[0])

def fdef(t):
    """Defuzzify via centroid method"""
    return (t[0] + t[1] + t[2]) / 3.0

def consistency_ratio(matrix):
    """CR = CI / RI  (Saaty 1980)"""
    n = matrix.shape[0]
    try:
        eig = eigvals(matrix.astype(float))
        lmax = np.max(np.real(eig))
        CI = (lmax - n) / (n - 1)
        RI_table = {3: 0.58, 4: 0.90, 5: 1.12, 6: 1.24, 7: 1.32}
        RI = RI_table.get(n, 1.12)
        CR = CI / RI if RI > 0 else np.nan
        return CR, lmax, CI
    except Exception:
        return np.nan, np.nan, np.nan

def fahp_weights(matrix):
    """Buckley (1985) fuzzy geometric mean"""
    n = matrix.shape[0]
    tfn = np.empty((n, n), dtype=object)
    for i in range(n):
        for j in range(n):
            tfn[i, j] = crisp_to_tfn(matrix[i, j])

    r_i = []
    for i in range(n):
        prod = tfn[i, 0]
        for j in range(1, n):
            prod = fmul(prod, tfn[i, j])
        r_i.append(fpow(prod, 1.0 / n))

    r_sum = r_i[0]
    for i in range(1, n):
        r_sum = fadd(r_sum, r_i[i])

    r_inv = frec(r_sum)
    w_fuzzy = [fmul(r_i[i], r_inv) for i in range(n)]
    w = np.array([fdef(x) for x in w_fuzzy])
    return w / w.sum()

