print(f"\n[P4-2/3] Shannon Entropy (1948)...")

def sample_paired(raster_paths, n_samples=50000, max_blocks=500,
                  grid_size=2048, seed=42):
    """Sample paired pixels from multiple rasters (for entropy)"""
    rng = np.random.default_rng(seed)
    with rasterio.open(raster_paths[0]) as s0:
        H, W = s0.height, s0.width
    srcs = [rasterio.open(p) for p in raster_paths]
    nodatas = [s.nodata for s in srcs]
    n_h = (H + grid_size - 1) // grid_size
    n_w = (W + grid_size - 1) // grid_size
    positions = [(i, j) for i in range(n_h) for j in range(n_w)]
    rng.shuffle(positions)
    collected = []
    total = 0
    for k, (i, j) in enumerate(positions):
        if k >= max_blocks or total >= n_samples * 1.5:
            break
        r = i * grid_size
        c = j * grid_size
        rs = min(r + grid_size, H)
        cs = min(c + grid_size, W)
        window = ((r, rs), (c, cs))
        blocks = []
        for m, src in enumerate(srcs):
            try:
                b = src.read(1, window=window).astype(np.float32)
            except Exception:
                break
            nd = nodatas[m]
            if nd is not None:
                b = np.where(b == nd, np.nan, b)
            b = np.where(b == SAFE_NODATA, np.nan, b)
            blocks.append(b.flatten())
        if len(blocks) != len(raster_paths):
            continue
        stacked = np.stack(blocks, axis=1)
        valid = np.all(np.isfinite(stacked), axis=1)
        vp = stacked[valid]
        if len(vp) > 0:
            if len(vp) > 5000:
                idx = rng.choice(len(vp), 5000, replace=False)
                vp = vp[idx]
            collected.append(vp)
            total += len(vp)
    for s in srcs:
        s.close()
    if not collected:
        return np.array([])
    data = np.vstack(collected)
    if len(data) > n_samples:
        idx = rng.choice(len(data), n_samples, replace=False)
        data = data[idx]
    return data

def min_max_norm(data):
    mn = data.min(axis=0)
    mx = data.max(axis=0)
    rng = mx - mn
    rng = np.where(rng == 0, 1.0, rng)
    return (data - mn) / rng

def shannon_weights(data_norm):
    """Shannon entropy weights (Zeleny 1982)"""
    N, K = data_norm.shape
    data_safe = np.abs(data_norm) + 1e-10
    cs = data_safe.sum(axis=0)
    cs = np.where(cs == 0, 1.0, cs)
    p = data_safe / cs
    ln_N = np.log(N)
    E = np.zeros(K)
    for k in range(K):
        pk = p[:, k]
        pk = pk[pk > 0]
        E[k] = -np.sum(pk * np.log(pk)) / ln_N
    E = np.clip(E, 0.0, 1.0 - 1e-6)
    d = np.maximum(1.0 - E, 1e-6)
    return d / d.sum(), E, d

