# ---- VIF ----
def compute_vif(data):
    """Variance Inflation Factor (Hair et al. 2010)"""
    N, K = data.shape
    vif = np.zeros(K)
    for k in range(K):
        others = [j for j in range(K) if j != k]
        X = data[:, others]
        y = data[:, k]
        X_int = np.column_stack([np.ones(N), X])
        try:
            XtX_inv = inv(X_int.T @ X_int)
            beta = XtX_inv @ X_int.T @ y
            y_pred = X_int @ beta
            ss_res = np.sum((y - y_pred) ** 2)
            ss_tot = np.sum((y - y.mean()) ** 2)
            r2 = 1 - ss_res / ss_tot if ss_tot > 0 else 0
            r2 = max(0, min(r2, 0.9999))
            vif[k] = 1.0 / (1.0 - r2)
        except Exception:
            vif[k] = np.nan
    return vif

