# ---- Ridge-regularized Game Theory ----
print(f"\n[P4-3/3] Ridge-regularized Game Theory (Chen 2023)...")

def game_theory_ridge(w_sub, w_obj, ridge=GAME_RIDGE):
    """
    Ridge-regularized Game Theory weight fusion.
    Prevents collapse to single weight vector.

    Solve: (A + ridge·I) α = b
    where A = Gram matrix of [w_sub, w_obj], b = diag(A)
    """
    a11 = float(np.dot(w_sub, w_sub))
    a12 = float(np.dot(w_sub, w_obj))
    a21 = float(np.dot(w_obj, w_sub))
    a22 = float(np.dot(w_obj, w_obj))
    A = np.array([[a11, a12], [a21, a22]])
    b = np.array([a11, a22])
    A_reg = A + ridge * np.eye(2)
    try:
        alpha = solve(A_reg, b)
    except LinAlgError:
        alpha = np.array([0.5, 0.5])
    alpha = np.maximum(alpha, 0.0)
    if alpha.sum() == 0:
        alpha = np.array([0.5, 0.5])
    alpha = alpha / alpha.sum()
    w = alpha[0] * w_sub + alpha[1] * w_obj
    w = np.maximum(w, 0.0)
    w = w / w.sum()
    return w, alpha

