print(f"  Base mean:          {base.mean():.4f}")

# Sanity check
assert base.min() >= -0.5, f"Base has unexpected negative values: {base.min()}"
assert base.max() <= 1.5, f"Base has unexpected large values: {base.max()}"

# ---- Bootstrap 5-fold CV ----
print(f"\n[P5-4/6] Bootstrap {N_BOOTSTRAP} × {N_FOLDS}-fold CV...")

bootstrap_results = []
for b in range(N_BOOTSTRAP):
    rng = np.random.default_rng(RANDOM_SEED + b * 137)
    indices = rng.permutation(n_points)
    fold_size = n_points // N_FOLDS
    fold_lam, fold_nu = [], []
    for k in range(N_FOLDS):
        start = k * fold_size
        end = start + fold_size if k < N_FOLDS - 1 else n_points
        cal_idx = np.setdiff1d(indices, indices[start:end])
        best_r = -np.inf
        b_l, b_n = 0.0, 0.0
        for lam in LAMBDA_GRID:
            for nu in NU_GRID:
                factor = (1.0 + lam * R_all) * (1.0 - nu * S_all)
                whri = base * factor
                wn = (whri - whri.min()) / (whri.max() - whri.min() + 1e-10)
                rho, _ = spearmanr(wn[cal_idx], target[cal_idx])
                if np.isfinite(rho) and rho > best_r:
                    best_r = rho
                    b_l, b_n = lam, nu
        fold_lam.append(b_l)
        fold_nu.append(b_n)
    bootstrap_results.append((np.mean(fold_lam), np.mean(fold_nu)))
    if (b + 1) % 5 == 0:
        print(f"  Bootstrap {b+1}/{N_BOOTSTRAP}")

bootstrap_results = np.array(bootstrap_results)
lambda_raw = float(LAMBDA_GRID[np.argmin(np.abs(LAMBDA_GRID - np.mean(bootstrap_results[:, 0])))])
