lambda_std = float(np.std(bootstrap_results[:, 0]))
nu_std = float(np.std(bootstrap_results[:, 1]))
lambda_ci_raw = np.percentile(bootstrap_results[:, 0], [2.5, 97.5])
nu_ci_raw = np.percentile(bootstrap_results[:, 1], [2.5, 97.5])

# Apply caps
