nu_final = min(nu_raw, NU_CAP)

# Compute CI for capped values (correct reporting)
lambda_capped_bs = np.minimum(bootstrap_results[:, 0], LAMBDA_CAP)
nu_capped_bs = np.minimum(bootstrap_results[:, 1], NU_CAP)
lambda_ci_capped = np.percentile(lambda_capped_bs, [2.5, 97.5])
nu_ci_capped = np.percentile(nu_capped_bs, [2.5, 97.5])

print(f"\n  Raw bootstrap: λ={lambda_raw:.2f}, ν={nu_raw:.2f}")
print(f"  Capped:        λ={lambda_final:.2f}, ν={nu_final:.2f}")
print(f"  λ (raw)    = {lambda_raw:.2f} ± {lambda_std:.2f}  "
      f"CI95(raw) = [{lambda_ci_raw[0]:.2f}, {lambda_ci_raw[1]:.2f}]")
print(f"  λ (capped) = {lambda_final:.2f}  "
      f"CI95(capped) = [{lambda_ci_capped[0]:.2f}, {lambda_ci_capped[1]:.2f}]")
print(f"  ν (raw)    = {nu_raw:.2f} ± {nu_std:.2f}  "
      f"CI95(raw) = [{nu_ci_raw[0]:.2f}, {nu_ci_raw[1]:.2f}]")
print(f"  ν (capped) = {nu_final:.2f}  "
      f"CI95(capped) = [{nu_ci_capped[0]:.2f}, {nu_ci_capped[1]:.2f}]")

factor = (1.0 + lambda_final * R_all) * (1.0 - nu_final * S_all)
whri_all = base * factor
whri_norm_all = (whri_all - whri_all.min()) / (whri_all.max() - whri_all.min() + 1e-10)
rho_full, p_full = spearmanr(whri_norm_all, target)

# 5-fold verification
rho_ver_list = []
rng = np.random.default_rng(RANDOM_SEED)
indices = rng.permutation(n_points)
fold_size = n_points // N_FOLDS
for k in range(N_FOLDS):
    start = k * fold_size
    end = start + fold_size if k < N_FOLDS - 1 else n_points
    ver_idx = indices[start:end]
    rho_v, _ = spearmanr(whri_norm_all[ver_idx], target[ver_idx])
    rho_ver_list.append(rho_v)

mean_rho_ver = float(np.mean(rho_ver_list))
std_rho_ver = float(np.std(rho_ver_list))

print(f"\n  Full ρ = {rho_full:.4f} (p = {p_full:.4e})")
print(f"  Mean ρ_ver = {mean_rho_ver:.4f} ± {std_rho_ver:.4f}")

# ---- Build WHRI raster ----
print(f"\n[P5-5/6] Building WHRI raster (Weighted Arithmetic Mean)...")

whri_raw_path = os.path.join(WHRI_DIR, "TBM_WHRI_v7_raw.tif")
whri_norm_path = os.path.join(WHRI_DIR, "TBM_WHRI_v7.tif")

fuzzy_srcs = {n: rasterio.open(p) for n, p in MAIN_FUZZY.items()}
R_src = rasterio.open(R_new_path)
S_src = rasterio.open(S_new_path)
W_array = np.array([W[i] for i in range(len(RAW_NAMES))], dtype=np.float32)

with rasterio.open(MAIN_FUZZY["TBM_NDVI"]) as src_ref:
    profile = src_ref.profile.copy()
    profile.update(dtype='float32', compress='lzw', nodata=SAFE_NODATA,
                   tiled=True, blockxsize=512, blockysize=512)

with rasterio.open(whri_raw_path, 'w', **profile) as dst:
    n_blocks = 0
    for ji, window in fuzzy_srcs["TBM_NDVI"].block_windows(1):
        blocks = []
        mask = np.ones((window.height, window.width), dtype=bool)
        for name in RAW_NAMES:
            b = fuzzy_srcs[name].read(1, window=window).astype(np.float32)
            nd = fuzzy_srcs[name].nodata
            valid = np.isfinite(b)
            if nd is not None:
                valid &= (b != nd)
            valid &= (b != SAFE_NODATA)
            mask &= valid
            b_safe = np.where(valid, b, 0.0)
            blocks.append(b_safe)

        X_stack = np.stack(blocks, axis=-1)
        base_block = X_stack @ W_array

        R_block = R_src.read(1, window=window).astype(np.float32)
        R_valid = np.isfinite(R_block)
        if R_src.nodata is not None:
            R_valid &= (R_block != R_src.nodata)
        R_valid &= (R_block != SAFE_NODATA)
        R_safe = np.where(R_valid, R_block, 0.5)

        S_block = S_src.read(1, window=window).astype(np.float32)
        S_valid = np.isfinite(S_block)
        if S_src.nodata is not None:
            S_valid &= (S_block != S_src.nodata)
        S_valid &= (S_block != SAFE_NODATA)
        S_safe = np.where(S_valid, S_block, 0.0)

        factor_block = (1.0 + lambda_final * R_safe) * (1.0 - nu_final * S_safe)
        whri = base_block * factor_block
        result = np.where(mask, whri, SAFE_NODATA).astype(np.float32)
        dst.write(result, 1, window=window)
        n_blocks += 1
        if n_blocks % 400 == 0:
            print(f"    {n_blocks} blocks...")

# Find global min/max
print(f"  Computing min/max...")
with rasterio.open(whri_raw_path) as src:
    rmin, rmax = np.inf, -np.inf
    for ji, window in src.block_windows(1):
        b = src.read(1, window=window).astype(np.float32)
        v = b[(b != SAFE_NODATA) & np.isfinite(b)]
        if len(v) > 0:
            rmin = min(rmin, float(v.min()))
            rmax = max(rmax, float(v.max()))
print(f"  Raw range: [{rmin:.4f}, {rmax:.4f}]")

# Normalize to [0, 1]
with rasterio.open(whri_raw_path) as src:
    with rasterio.open(whri_norm_path, 'w', **profile) as dst:
        for ji, window in src.block_windows(1):
            b = src.read(1, window=window).astype(np.float32)
            m = (b != SAFE_NODATA) & np.isfinite(b)
            norm = (b - rmin) / (rmax - rmin + 1e-10)
            dst.write(np.where(m, norm, SAFE_NODATA).astype(np.float32), 1, window=window)

for s in fuzzy_srcs.values():
    s.close()
R_src.close()
S_src.close()
gc.collect()
