# ---- Classification (Jenks) ----
print(f"\n[P5-6/6] Classification (Jenks Natural Breaks 1967)...")

sample_values = []
with rasterio.open(whri_norm_path) as src:
    H, W = src.height, src.width
    rng = np.random.default_rng(RANDOM_SEED)
    grid_size = 2048
    n_h = (H + grid_size - 1) // grid_size
    n_w = (W + grid_size - 1) // grid_size
    positions = [(i, j) for i in range(n_h) for j in range(n_w)]
    rng.shuffle(positions)
    total = 0
    for i, j in positions:
        if total >= JENKS_SAMPLE * 2:
            break
        r = i * grid_size
        c = j * grid_size
        rs = min(r + grid_size, H)
        cs = min(c + grid_size, W)
        try:
            b = src.read(1, window=((r, rs), (c, cs))).astype(np.float32)
        except Exception:
            continue
        v = b[(b != SAFE_NODATA) & np.isfinite(b)]
        if len(v) > 0:
            n_take = min(3000, len(v))
            idx = rng.choice(len(v), n_take, replace=False)
            sample_values.append(v[idx])
            total += n_take

sample_values = np.concatenate(sample_values)
if len(sample_values) > JENKS_SAMPLE:
    idx = np.random.choice(len(sample_values), JENKS_SAMPLE, replace=False)
    sample_values = sample_values[idx]

breaks = jenkspy.jenks_breaks(sample_values, n_classes=5)
print(f"  Breaks: {[round(float(b), 4) for b in breaks]}")

whri_classified = os.path.join(WHRI_DIR, "TBM_WHRI_v7_Classified.tif")
whri_zones = os.path.join(WHRI_DIR, "TBM_WHRI_v7_Zones.tif")

with rasterio.open(whri_norm_path) as src:
    profile_c = src.profile.copy()
    profile_c.update(dtype='uint8', nodata=255)

    all_values = []
    for ji, window in src.block_windows(1):
        b = src.read(1, window=window).astype(np.float32)
        v = b[(b != SAFE_NODATA) & np.isfinite(b)]
        if len(v) > 0:
            if len(v) > 10000:
                idx = np.random.choice(len(v), 10000, replace=False)
                v = v[idx]
            all_values.append(v)

    all_values = np.concatenate(all_values)
    mean_whri = float(all_values.mean())
    std_whri = float(all_values.std())
    median_whri = float(np.median(all_values))
    min_whri = float(all_values.min())
    max_whri = float(all_values.max())
    p25 = float(np.percentile(all_values, 25))
    p75 = float(np.percentile(all_values, 75))
    skewness = float(pd.Series(all_values).skew())
    kurtosis = float(pd.Series(all_values).kurtosis())

    # Class and Zone boundaries use the same logic (last class inclusive)
    with rasterio.open(whri_classified, 'w', **profile_c) as dc:
        with rasterio.open(whri_zones, 'w', **profile_c) as dz:
            for ji, window in src.block_windows(1):
                b = src.read(1, window=window).astype(np.float32)
                m = (b != SAFE_NODATA) & np.isfinite(b)

                # 5 classes (consistent boundaries with last class inclusive)
                cls = np.zeros(b.shape, dtype=np.uint8)
                cls[(b >= breaks[0]) & (b < breaks[1])] = 1
                cls[(b >= breaks[1]) & (b < breaks[2])] = 2
                cls[(b >= breaks[2]) & (b < breaks[3])] = 3
                cls[(b >= breaks[3]) & (b < breaks[4])] = 4
                cls[(b >= breaks[4]) & (b <= breaks[5])] = 5
                # Pixels below breaks[0] or above breaks[5] get clipped
                cls[b < breaks[0]] = 1
                cls[b > breaks[5]] = 5
                dc.write(np.where(m, cls, 255).astype(np.uint8), 1, window=window)

                # 3 zones (same boundary logic as classes)
                z = np.zeros(b.shape, dtype=np.uint8)
                z[b < breaks[2]] = 1                    # Critical
                z[(b >= breaks[2]) & (b < breaks[3])] = 2  # Semi-critical
                z[b >= breaks[3]] = 3                   # Reference
                dz.write(np.where(m, z, 255).astype(np.uint8), 1, window=window)

print(f"  ✓ Classified + Zones saved")

