# ============================================================
# WHRI corrected raster writer (tile-by-tile, memory-safe)
# ============================================================

def save_whri_health_raster(whri_path, out_dir, tile_size=WHRI_TILE_SIZE):
    """
    Reflect WHRI around its midpoint: WHRI_health = wmax + wmin - WHRI.
    Memory-bounded: reads/writes one tile at a time.
    Returns the output path, or None on failure.
    """
    out_raster = os.path.join(out_dir, "TBM_WHRI_health.tif")

    # Rerun-safe: if already saved within 24h, skip
    if os.path.exists(out_raster):
        age_h = (datetime.datetime.now().timestamp() -
                 os.path.getmtime(out_raster)) / 3600
        if age_h < 24:
            _p(f"  ✓ Corrected raster exists ({age_h:.1f}h old) — reusing")
            return out_raster

    try:
        with rasterio.open(whri_path) as src:
            H, W = src.height, src.width
            profile = src.profile.copy()
            nodata = (src.nodata if src.nodata is not None else SAFE_NODATA)

            # ---- Pass 1: global min/max ----
            _p("  [WHRI] pass 1: computing global min/max ...")
            gmin, gmax = np.inf, -np.inf
            n_tiles = 0
            for r0 in range(0, H, tile_size):
                for c0 in range(0, W, tile_size):
                    r1 = min(H, r0 + tile_size)
                    c1 = min(W, c0 + tile_size)
                    blk = src.read(1, window=Window(c0, r0,
                                                     c1 - c0, r1 - r0)
                                    ).astype(np.float32)
                    blk = np.where(blk == nodata, np.nan, blk)
                    if np.isfinite(blk).any():
                        gmin = min(gmin, float(np.nanmin(blk)))
                        gmax = max(gmax, float(np.nanmax(blk)))
                    n_tiles += 1
                    if n_tiles % 50 == 0:
                        _p(f"    {n_tiles} tiles scanned ...")
                        gc.collect()

            if not np.isfinite(gmin) or not np.isfinite(gmax):
                _p("  ⚠️ No finite values in WHRI — skipping save")
                return None

            _p(f"  [WHRI] range: [{gmin:.4f}, {gmax:.4f}]")

            # ---- Pass 2: write corrected ----
            _p("  [WHRI] pass 2: writing corrected raster ...")
            profile.update(dtype=rasterio.float32, nodata=nodata)
            with rasterio.open(out_raster, "w", **profile) as dst:
                n_tiles = 0
                for r0 in range(0, H, tile_size):
                    for c0 in range(0, W, tile_size):
                        r1 = min(H, r0 + tile_size)
                        c1 = min(W, c0 + tile_size)
                        w = Window(c0, r0, c1 - c0, r1 - r0)
                        blk = src.read(1, window=w).astype(np.float32)
                        msk = (blk == nodata) | ~np.isfinite(blk)
                        corr = (gmax + gmin) - blk
                        corr[msk] = nodata
                        dst.write(corr.astype(np.float32), 1, window=w)
                        n_tiles += 1
                        if n_tiles % 50 == 0:
                            _p(f"    {n_tiles} tiles written ...")
                            gc.collect()

        _p(f"  ✓ Saved: {out_raster}")
        return out_raster

    except Exception as e:
        _p(f"  ⚠️ WHRI save failed: {e}")
        return None


# ============================================================
# RASTER I/O (fast per-point windows)
# ============================================================

def _raster_info(path):
    with rasterio.open(path) as src:
        return src.height, src.width


def sample_point(path, coords, max_radius_px=200):
    """Point sampling. Fallback to local window search on nodata."""
    coords_arr = np.asarray(coords, dtype=np.float64)
    n = len(coords_arr)
    out = np.full(n, np.nan, dtype=np.float32)

    with rasterio.open(path) as src:
        nodata = src.nodata
        H, W = src.height, src.width
        pts = [(float(x), float(y)) for x, y in coords_arr]
        vals = np.fromiter((v[0] for v in src.sample(pts)),
                            dtype=np.float32, count=n)
        if nodata is not None:
            vals = np.where(vals == nodata, np.nan, vals)
        vals = np.where(vals == SAFE_NODATA, np.nan, vals)
        out[:] = vals

        bad = np.where(~np.isfinite(out))[0]
        if len(bad) == 0:
            return out

        radii = [5, 10, 20, 50, 100, max_radius_px]
        for i in bad:
            x, y = pts[i]
            try:
                row, col = src.index(x, y)
            except Exception:
                continue
            if row < 0 or row >= H or col < 0 or col >= W:
                continue
            for r in radii:
                if r > max_radius_px:
                    break
                r0 = max(0, row - r)
                c0 = max(0, col - r)
                r1 = min(H, row + r + 1)
                c1 = min(W, col + r + 1)
                try:
                    blk = src.read(1, window=Window(c0, r0,
                                                     c1 - c0, r1 - r0)
                                    ).astype(np.float32)
                except Exception:
                    break
                if nodata is not None:
                    blk = np.where(blk == nodata, np.nan, blk)
                blk = np.where(blk == SAFE_NODATA, np.nan, blk)
                v = np.isfinite(blk)
                if v.any():
                    cy = row - r0
                    cx = col - c0
                    ys, xs = np.where(v)
                    d = (ys - cy) ** 2 + (xs - cx) ** 2
                    k = int(np.argmin(d))
                    out[i] = blk[ys[k], xs[k]]
                    break
    return out


def sample_multiscale_buffers(path, coords, scales_px, min_valid_frac=0.3,
                                progress_every=50):
    """
    Read one max-radius window per point; compute all scales from it.
    scales_px: dict {scale_m: radius_px}
    """
    coords_arr = np.asarray(coords, dtype=np.float64)
    n = len(coords_arr)
    scales_sorted = sorted(scales_px.items(), key=lambda x: x[1])
    max_r = max(scales_px.values())
    out = {s: np.full(n, np.nan, dtype=np.float32) for s in scales_px}

    with rasterio.open(path) as src:
        nodata = src.nodata
        H, W = src.height, src.width

        for i, (x, y) in enumerate(coords_arr):
            if i % progress_every == 0 and i > 0:
                _p(f"      {i}/{n} points...")

            try:
                row, col = src.index(float(x), float(y))
            except Exception:
                continue
            if row < 0 or row >= H or col < 0 or col >= W:
                continue

            r0 = max(0, row - max_r)
            c0 = max(0, col - max_r)
            r1 = min(H, row + max_r + 1)
            c1 = min(W, col + max_r + 1)

            try:
                blk = src.read(1, window=Window(c0, r0, c1 - c0, r1 - r0)
                                ).astype(np.float32)
            except Exception:
                continue

            if nodata is not None:
                blk = np.where(blk == nodata, np.nan, blk)
            blk = np.where(blk == SAFE_NODATA, np.nan, blk)

            cy = row - r0
            cx = col - c0
            yy, xx = np.indices(blk.shape)
            dist2 = (yy - cy) ** 2 + (xx - cx) ** 2

            for scale_m, r_px in scales_sorted:
                mask = dist2 <= r_px ** 2
                n_total = int(mask.sum())
                if n_total == 0:
                    continue
                vals = blk[mask]
                valid = np.isfinite(vals)
                if valid.sum() / n_total >= min_valid_frac:
                    out[scale_m][i] = float(vals[valid].mean())

    return out


