def spatial_kfold(cx, cy, n_folds=5, seed=42):
    coords = np.column_stack([cx, cy])
    coords_norm = (coords - coords.mean(0)) / (coords.std(0) + 1e-10)
    return KMeans(n_clusters=n_folds, random_state=seed,
                   n_init=5).fit_predict(coords_norm)


def compute_variogram_range(coords, values, max_lag=None, n_bins=15):
    n = len(coords)
    if n < 20:
        return None, [], []
    if n > 300:
        idx = np.random.default_rng(RANDOM_SEED).choice(n, 300, replace=False)
        cs, vs = coords[idx], values[idx]
    else:
        cs, vs = coords, values
    if max_lag is None:
        max_lag = float(np.median(pdist(cs))) * 2
    pairs = cKDTree(cs).query_pairs(max_lag, output_type="ndarray")
    if len(pairs) < 20:
        return None, [], []
    d = np.sqrt(((cs[pairs[:, 0]] - cs[pairs[:, 1]]) ** 2).sum(1))
    sv = 0.5 * (vs[pairs[:, 0]] - vs[pairs[:, 1]]) ** 2
    edges = np.linspace(0, max_lag, n_bins + 1)
    centers = (edges[:-1] + edges[1:]) / 2
    bsv = np.full(n_bins, np.nan)
    for k in range(n_bins):
        m = (d >= edges[k]) & (d < edges[k + 1])
        if m.sum() >= 5:
            bsv[k] = sv[m].mean()
    if np.isfinite(bsv).sum() < 3:
        return None, [], []
    n_last = max(3, n_bins // 3)
    sill = np.nanmean(bsv[-n_last:])
    for k in range(n_bins):
        if np.isfinite(bsv[k]) and bsv[k] >= 0.95 * sill:
            return float(centers[k]), centers.tolist(), bsv.tolist()
    return float(centers[-1]), centers.tolist(), bsv.tolist()


def compute_max_depth(n_train, n_features):
    log2_n = np.log2(max(n_train, 2))
    if n_features == 1:
        return max(3, int(np.ceil(log2_n)))
    elif n_features <= 3:
        return max(4, int(np.ceil(log2_n)) + 2)
    return max(6, int(np.ceil(2 * log2_n)))


def compute_vif(X):
    n, p = X.shape
    vif = np.full(p, np.nan)
    for i in range(p):
        Xo = np.delete(X, i, axis=1)
        r2_i = LinearRegression().fit(Xo, X[:, i]).score(Xo, X[:, i])
        vif[i] = 1.0 / max(1.0 - r2_i, 1e-10)
    return vif


def bh_fdr(p_values, alpha=0.05):
    p = np.asarray(p_values, float)
    n = len(p)
    order = np.argsort(p)
    q = p[order] * n / np.arange(1, n + 1)
    q = np.minimum.accumulate(q[::-1])[::-1]
    q = np.minimum(q, 1.0)
    adj = np.empty(n)
    adj[order] = q
    return adj <= alpha, adj


def safe_spearman(a, b, min_n=5):
    a = np.asarray(a, float); b = np.asarray(b, float)
    m = np.isfinite(a) & np.isfinite(b)
    if m.sum() < min_n:
        return np.nan, np.nan
    a, b = a[m], b[m]
    if np.std(a) < 1e-12 or np.std(b) < 1e-12:
        return np.nan, np.nan
    with warnings.catch_warnings():
        warnings.simplefilter("ignore")
        rho, p = spearmanr(a, b)
    return (float(rho) if np.isfinite(rho) else np.nan,
            float(p) if np.isfinite(p) else np.nan)


def safe_kendall(a, b, min_n=5):
    a = np.asarray(a, float); b = np.asarray(b, float)
    m = np.isfinite(a) & np.isfinite(b)
    if m.sum() < min_n:
        return np.nan, np.nan
    a, b = a[m], b[m]
    if np.std(a) < 1e-12 or np.std(b) < 1e-12:
        return np.nan, np.nan
    with warnings.catch_warnings():
        warnings.simplefilter("ignore")
        tau, p = kendalltau(a, b)
    return (float(tau) if np.isfinite(tau) else np.nan,
            float(p) if np.isfinite(p) else np.nan)


def exact_permutation_spearman(x, y, max_n=8):
    x = np.asarray(x, float); y = np.asarray(y, float)
    m = np.isfinite(x) & np.isfinite(y)
    if m.sum() < 4:
        return np.nan, np.nan, 0
    x, y = x[m], y[m]
    n = len(x)
    if np.std(x) < 1e-12 or np.std(y) < 1e-12:
        return np.nan, np.nan, 0
    rx = rankdata(x); ry = rankdata(y)
    obs = np.corrcoef(rx, ry)[0, 1]
    if not np.isfinite(obs):
        return np.nan, np.nan, 0
    cnt = 0
    nperm = 0
    if n <= max_n:
        for perm in itertools.permutations(range(n)):
            r = np.corrcoef(rx, ry[np.array(perm)])[0, 1]
            if np.isfinite(r) and abs(r) >= abs(obs) - 1e-12:
                cnt += 1
            nperm += 1
        return obs, cnt / nperm, nperm
    rng = np.random.default_rng(RANDOM_SEED)
    for _ in range(5000):
        r = np.corrcoef(rx, rng.permutation(ry))[0, 1]
        if np.isfinite(r) and abs(r) >= abs(obs) - 1e-12:
            cnt += 1
        nperm += 1
    return obs, (cnt + 1) / (nperm + 1), nperm


def prepare_X(cols, names):
    X = np.column_stack(cols)
    for j in range(X.shape[1]):
        col = X[:, j]
        m = ~np.isfinite(col)
        if m.any():
            col[m] = np.nanmedian(col)
    return X


def evaluate_model_cv(X, y, folds, model_factory, n_folds,
                       coords=None, buffer_m=None, clip_predict=False,
                       skip_linear_below_n=None, is_linear=False):
    n = len(y)
    oof = np.full(n, np.nan)
    met = {"r2": [], "rmse": [], "mae": [], "spearman": [],
           "n_train_used": [], "n_test_used": [], "n_folds_skipped": 0}
    for fold in range(n_folds):
        test_idx = np.where(folds == fold)[0]
        train_idx = np.where(folds != fold)[0]
        if coords is not None and buffer_m is not None and buffer_m > 0:
            tree = cKDTree(coords[test_idx])
            d, _ = tree.query(coords[train_idx], k=1)
            train_idx = train_idx[d > buffer_m]
        if len(test_idx) < MIN_TEST_N or len(train_idx) < MIN_TRAIN_N:
            met["n_folds_skipped"] += 1
            continue
        if is_linear and skip_linear_below_n is not None:
            if len(train_idx) < skip_linear_below_n:
                met["n_folds_skipped"] += 1
                continue
        model = model_factory()
        model.fit(X[train_idx], y[train_idx])
        yp = model.predict(X[test_idx])
        if clip_predict:
            yp = np.clip(yp, 0.0, 1.0)
        oof[test_idx] = yp
        met["r2"].append(r2_score(y[test_idx], yp))
        met["rmse"].append(np.sqrt(mean_squared_error(y[test_idx], yp)))
        met["mae"].append(mean_absolute_error(y[test_idx], yp))
        if len(test_idx) >= MIN_TEST_N_FOR_SPEARMAN:
            rho, _ = safe_spearman(y[test_idx], yp)
            met["spearman"].append(rho)
        else:
            met["spearman"].append(np.nan)
        met["n_train_used"].append(len(train_idx))
        met["n_test_used"].append(len(test_idx))
    return oof, met


