def find_fuzzy(cands):
    folders = [
        os.path.join(INTERMEDIATE, "fuzzy_v7"),
        os.path.join(INTERMEDIATE, "fuzzy_v6"),
        os.path.join(INTERMEDIATE, "fuzzy_v5"),
        os.path.join(INTERMEDIATE, "fuzzy"),
        REPROJ_DIR,
    ]
    for f in folders:
        if not os.path.exists(f):
            continue
        for n in cands:
            p = os.path.join(f, n)
            if os.path.exists(p):
                return p
    return None


