def _json_safe(v):
    """NaN/Inf/pd.NA → None for valid JSON."""
    if v is None:
        return None
    try:
        if pd.isna(v):
            return None
    except (TypeError, ValueError):
        pass
    try:
        fv = float(v)
    except (TypeError, ValueError):
        return v
    return fv if np.isfinite(fv) else None


def _get_s2(si_dict, key):
    """Array-safe extraction of S2/S2_conf from a SALib result dict."""
    v = si_dict.get(key, None)
    if v is None:
        return []
    try:
        arr = np.asarray(v)
        return arr if arr.size > 0 else []
    except Exception:
        return []


