def _p(msg=""):
    print(msg, flush=True)


def _json_safe(v):
    if v is None:
        return None
    try:
        if pd.isna(v):
            return None
    except (TypeError, ValueError):
        pass
    try:
        fv = float(v)
    except (TypeError, ValueError):
        return v
    return fv if np.isfinite(fv) else None


# ============================================================
# CHECKPOINT HELPERS
# ============================================================

def _load_ckpt():
    if os.path.exists(CKPT_PATH):
        try:
            with open(CKPT_PATH, "r", encoding="utf-8") as f:
                c = json.load(f)
            return {
                "phase_a_done": int(c.get("phase_a_done", 0)),
                "phase_a_finished": bool(c.get("phase_a_finished", False)),
                "phase_b_finished": bool(c.get("phase_b_finished", False)),
                "version": c.get("version", "unknown"),
            }
        except Exception as e:
            _p(f"  ⚠️ checkpoint read error: {e}")
    return {"phase_a_done": 0, "phase_a_finished": False,
            "phase_b_finished": False, "version": "unknown"}


def _save_ckpt(ckpt):
    ckpt["version"] = CURRENT_VERSION
    tmp = CKPT_PATH + ".tmp"
    with open(tmp, "w", encoding="utf-8") as f:
        json.dump(ckpt, f, ensure_ascii=False, indent=2)
    os.replace(tmp, CKPT_PATH)


def _load_done_tiles():
    if not os.path.exists(PHASE_B_TILES):
        return set()
    done = set()
    with open(PHASE_B_TILES, "r") as f:
        for line in f:
            line = line.strip()
            if not line:
                continue
            try:
                r_str, c_str = line.split(",")
                done.add((int(r_str), int(c_str)))
            except Exception:
                continue
    return done


def _save_done_tiles(done_set):
    tmp = PHASE_B_TILES + ".tmp"
    with open(tmp, "w") as f:
        for r, c in sorted(done_set):
            f.write(f"{r},{c}\n")
    os.replace(tmp, PHASE_B_TILES)


# ============================================================
# AUTO-CLEANUP HELPER
# ============================================================

def _safe_remove(path, label):
    """Remove a file with logging. Silent if missing."""
    if os.path.exists(path):
        try:
            sz_mb = os.path.getsize(path) / 1e6
            os.remove(path)
            _p(f"     - removed {label:30s} ({sz_mb:.1f} MB)")
            return True
        except Exception as e:
            _p(f"     ⚠️ failed to remove {label}: {e}")
            return False
    return False


def _invalidate_all(ckpt):
    """
    Delete ALL Phase A and Phase B artifacts, reset checkpoint flags.
    Called when version mismatch is detected.
    """
    _p("\n     Cleaning up Phase A artifacts ...")
    _safe_remove(PHASE_A_NPY, "mc_phase_a.npy")

    _p("     Cleaning up Phase B artifacts ...")
    _safe_remove(PHASE_B_TILES, "mc_phase_b_tiles.txt")
    for path in MC_OUTPUTS:
        _safe_remove(path, os.path.basename(path))

    _p("     Cleaning up auxiliary files ...")
    _safe_remove(CONV_PATH, "mc_convergence.csv")
    _safe_remove(OUT_JSON, "mc_results_v7.json")

    # Reset checkpoint
    ckpt["phase_a_done"] = 0
    ckpt["phase_a_finished"] = False
    ckpt["phase_b_finished"] = False
    _save_ckpt(ckpt)


