def find_raster(cands):
    for folder in [FUZZY_DIR,
                   os.path.join(INTERMEDIATE, "fuzzy_v6"),
                   os.path.join(INTERMEDIATE, "fuzzy"),
                   os.path.join(INTERMEDIATE, "reprojected")]:
        if not os.path.exists(folder):
            continue
        for n in cands:
            p = os.path.join(folder, n)
            if os.path.exists(p):
                return p
    return None


