        n_bin = int(binary.sum())
        if n_bin > 0:
            labeled, _ = nd_label(binary)
            from collections import Counter
            sizes = Counter(labeled.ravel().tolist())
            sizes.pop(0, None)
            top = sorted(sizes.items(), key=lambda x: -x[1])[:TOPN_HOTSPOTS]
            for comp_id, comp_size in top:
                ys, xs = np.where(labeled == comp_id)
                cy_sub = float(ys.mean()) * STRIDE_FIG
                cx_sub = float(xs.mean()) * STRIDE_FIG
                x_utm, y_utm = src.xy(cy_sub, cx_sub)
                area_px = comp_size * (STRIDE_FIG ** 2)
