def read_subsampled(path, stride=STRIDE_FIG, categorical=False):
    with rasterio.open(path) as src:
        h_out = max(1, src.height // stride)
        w_out = max(1, src.width // stride)
        method = Resampling.nearest if categorical else Resampling.bilinear
        arr = src.read(1, out_shape=(h_out, w_out),
                        resampling=method).astype(np.float32)
        nd = src.nodata
        if nd is not None:
            arr = np.where(arr == nd, np.nan, arr)
        arr = np.where(arr == SAFE_NODATA, np.nan, arr)
    return arr


def plot_panel(ax, arr, cmap, vmin, vmax, title,
                add_colorbar=False, colorbar_label="",
                legend_handles=None, legend_kwargs=None,
                colorbar_ax=None):
    """
    Plot one aligned panel with basin boundary.
    If colorbar_ax is provided, the colorbar is placed there
    (keeps panels the same width across subplots).
    """
    im = ax.imshow(arr, cmap=cmap, vmin=vmin, vmax=vmax,
                    extent=EXTENT, origin="upper",
                    interpolation="nearest", aspect="equal", zorder=1)

    if boundary_gdf is not None:
        try:
            boundary_gdf.boundary.plot(ax=ax, zorder=5, **BOUNDARY_KW)
        except Exception:
            pass

    ax.set_xlim(EXTENT[0], EXTENT[1])
    ax.set_ylim(EXTENT[2], EXTENT[3])
    ax.set_aspect("equal")
    ax.set_title(title, fontsize=11, loc="left", pad=6)
    ax.set_xticks([]); ax.set_yticks([])

    if add_colorbar and colorbar_ax is not None:
        cb = plt.colorbar(im, cax=colorbar_ax)
        if colorbar_label:
            cb.set_label(colorbar_label, fontsize=10)

    if legend_handles:
        lk = dict(loc="lower left", fontsize=6.5, framealpha=0.92, ncol=2)
        if legend_kwargs:
            lk.update(legend_kwargs)
        ax.legend(handles=legend_handles, **lk)

    return im


