def _safe(v):
    try:
        fv = float(v)
        return fv if np.isfinite(fv) else None
    except (TypeError, ValueError):
        return v


def _file_hash(path, block_size=65536):
    """SHA-256 hash of file content for dedup."""
    h = hashlib.sha256()
    try:
        with open(path, "rb") as f:
            while True:
                chunk = f.read(block_size)
                if not chunk:
                    break
                h.update(chunk)
        return h.hexdigest()
    except Exception:
        return None


