# ============================================================
# CRS-aware reader
# ============================================================

def read_raster_paired(path, positions, block_size=256):
    vals_all = []
    target_size = block_size * block_size
    try:
        src = rasterio.open(path)
    except Exception:
        return np.full(target_size * len(positions), np.nan)

    with src:
        nd = src.nodata
        src_H, src_W = src.height, src.width
        src_crs = src.crs
        need_reproj = (src_crs is not None and src_crs != CRS_REF)

        for (r0, c0) in positions:
            x_ref, y_ref = TRANSFORM_REF * (c0, r0)
            if need_reproj:
                try:
                    xs, ys = rio_transform(CRS_REF, src_crs,
                                            [x_ref], [y_ref])
                    x_src, y_src = xs[0], ys[0]
                except Exception:
                    vals_all.append(np.full(target_size, np.nan))
                    continue
            else:
                x_src, y_src = x_ref, y_ref

            try:
                src_r, src_c = src.index(x_src, y_src)
            except Exception:
                vals_all.append(np.full(target_size, np.nan))
                continue

            r1 = max(0, min(src_H, src_r + block_size))
            c1 = max(0, min(src_W, src_c + block_size))
            if r1 <= src_r or c1 <= src_c:
                vals_all.append(np.full(target_size, np.nan))
                continue

            win = Window(src_c, src_r, c1 - src_c, r1 - src_r)
            try:
                b = src.read(1, window=win)
            except Exception:
                vals_all.append(np.full(target_size, np.nan))
                continue

            b = b.astype(np.float64)
            if nd is not None:
                try:
                    b = np.where(b == float(nd), np.nan, b)
                except Exception:
                    pass
            b = np.where(b == SAFE_NODATA, np.nan, b)
            b = np.where(np.abs(b) > 1e30, np.nan, b)
            b = b.astype(np.float32)

            b_flat = b.ravel()
            if b_flat.size < target_size:
                b_flat = np.concatenate(
                    [b_flat, np.full(target_size - b_flat.size, np.nan)])
            else:
                b_flat = b_flat[:target_size]
            vals_all.append(b_flat)

    return np.concatenate(vals_all)


