def compute_vif(X):
    corr = np.corrcoef(X, rowvar=False)
    corr = np.nan_to_num(corr, nan=0.0)
    np.fill_diagonal(corr, 1.0)
    cond = float(np.linalg.cond(corr))
    try:
        if cond > 1e12:
            inv_corr = np.linalg.pinv(corr)
        else:
            inv_corr = np.linalg.inv(corr)
        vif = np.diag(inv_corr)
        vif = np.where(vif < 0, np.nan, vif)
    except Exception:
        vif = np.full(len(corr), np.nan)
    return vif, cond, corr


def sample_aligned(names, n_blocks=30, block_size=256):
    rng = np.random.default_rng(RANDOM_SEED + 100)
    positions = [
        (int(rng.integers(0, max(1, H_REF - block_size))),
         int(rng.integers(0, max(1, W_REF - block_size))))
        for _ in range(n_blocks)
    ]

    data = {}
    for name in names:
        if name not in INDICATOR_PATH_MAP:
            continue
        path = INDICATOR_PATH_MAP[name]["full_path"]
        if not os.path.exists(path):
            continue

        if "Subsidence" in name:
            rng_s = np.random.default_rng(RANDOM_SEED + 500)
            pos_s = [
                (int(rng_s.integers(0, max(1, H_REF - 128))),
                 int(rng_s.integers(0, max(1, W_REF - 128))))
                for _ in range(300)
            ]
            vals = read_raster_paired(path, pos_s, block_size=128)
        else:
            vals = read_raster_paired(path, positions,
                                        block_size=block_size)

        if np.isfinite(vals).sum() > 500:
            data[name] = vals

    if len(data) < 2:
        return None, None, None

    keys = list(data.keys())
    min_len = min(len(v) for v in data.values())
    X = np.full((min_len, len(keys)), np.nan, dtype=np.float64)
    for j, k in enumerate(keys):
        X[:, j] = data[k][:min_len]

    valid = np.all(np.isfinite(X), axis=1)
    X = X[valid]
    if X.shape[0] < 500:
        return None, None, None

    col_std = X.std(axis=0)
    keep = col_std > 1e-9
    return X[:, keep], [keys[i] for i in range(len(keys)) if keep[i]], data


