vhc_p = INDICATOR_PATH_MAP.get(
    "TBM_VegetationHealthComposite", {}).get("full_path")

ndvi_report = [
    "=" * 70,
    "VEGETATION INDEX COLLINEARITY (NDVI vs NDRE)",
    "=" * 70,
    "",
    "Purpose: quantify redundancy between NDVI and NDRE when both",
    "feed into the Vegetation Health Composite (VHC).",
    "",
    "NDVI and NDRE are strongly correlated in most landscapes.",
    "Including both in the same composite can inflate the weight of",
    "vegetation information. This section diagnoses whether the",
    "substitution documented in the config is justified by the data.",
    "",
    "-" * 70,
]
ndvi_final_status = "NOT_EVALUATED"

if all(p and os.path.exists(p) for p in [ndvi_p, ndre_p, vhc_p]):
    rng_c = np.random.default_rng(RANDOM_SEED + 250)
    pos_c = [
        (int(rng_c.integers(0, max(1, H_REF - 512))),
         int(rng_c.integers(0, max(1, W_REF - 512))))
        for _ in range(20)
    ]

    ndvi_v = read_raster_paired(ndvi_p, pos_c, block_size=512)
    ndre_v = read_raster_paired(ndre_p, pos_c, block_size=512)
    vhc_v = read_raster_paired(vhc_p, pos_c, block_size=512)

    n_min = min(len(ndvi_v), len(ndre_v), len(vhc_v))
    valid = (np.isfinite(ndvi_v[:n_min])
             & np.isfinite(ndre_v[:n_min])
             & np.isfinite(vhc_v[:n_min]))
    ndvi_c = ndvi_v[:n_min][valid]
    ndre_c = ndre_v[:n_min][valid]
    vhc_c = vhc_v[:n_min][valid]

    if len(ndvi_c) > 1000:
        rho_ndvi_ndre, _ = spearmanr(ndvi_c, ndre_c)
        rho_vhc_ndvi, _ = spearmanr(vhc_c, ndvi_c)
        rho_vhc_ndre, _ = spearmanr(vhc_c, ndre_c)

        def partial_corr_pearson(x, y, z):
            x_s = (x - x.mean()) / (x.std() + 1e-9)
            y_s = (y - y.mean()) / (y.std() + 1e-9)
            z_s = (z - z.mean()) / (z.std() + 1e-9)
            beta_xz = np.polyfit(z_s, x_s, 1)[0]
            beta_yz = np.polyfit(z_s, y_s, 1)[0]
            x_res = x_s - beta_xz * z_s
            y_res = y_s - beta_yz * z_s
            r, _ = pearsonr(x_res, y_res)
            return float(r)

        pcorr_vhc_ndvi = partial_corr_pearson(vhc_c, ndvi_c, ndre_c)
        pcorr_vhc_ndre = partial_corr_pearson(vhc_c, ndre_c, ndvi_c)
        DIFF = abs(pcorr_vhc_ndre) - abs(pcorr_vhc_ndvi)
        COLLINEARITY_THRESHOLD = 0.7

        ndvi_report.extend([
            "  N valid pixels: {0:,}".format(len(ndvi_c)),
            "  rho(NDVI, NDRE) = {0:+.4f}".format(rho_ndvi_ndre),
            "  rho(VHC, NDVI) = {0:+.4f}".format(rho_vhc_ndvi),
            "  rho(VHC, NDRE) = {0:+.4f}".format(rho_vhc_ndre),
            "  r(VHC, NDVI | NDRE) = {0:+.4f}".format(pcorr_vhc_ndvi),
            "  r(VHC, NDRE | NDVI) = {0:+.4f}".format(pcorr_vhc_ndre),
            "  Difference = {0:+.4f}".format(DIFF),
            "",
        ])

        if abs(rho_ndvi_ndre) > COLLINEARITY_THRESHOLD:
            ndvi_report.extend([
                "  DIAGNOSIS: HIGH COLLINEARITY ({0:.4f} > {1})".format(
                    abs(rho_ndvi_ndre), COLLINEARITY_THRESHOLD),
                "",
                "  Config documents:",
                "    substitute_in_vhc = {0}".format(
                    CFG["analysis_params"]["ndvi_handling"].get(
                        "substitute_in_vhc", "?")),
                "    substitute_in_R   = {0}".format(
                    CFG["analysis_params"]["ndvi_handling"].get(
                        "substitute_in_R", "?")),
                "",
                "  ACTION: Retain NDRE substitution as documented.",
            ])
            ndvi_final_status = "RESOLVED_HIGH_COLLINEARITY"
        elif DIFF > 0.05:
            ndvi_final_status = "NDRE_DOMINANT"
            ndvi_report.append("  CONCLUSION: NDRE dominant.")
        elif DIFF < -0.05:
            ndvi_final_status = "NDVI_DOMINANT"
            ndvi_report.append("  [!] INVESTIGATE: NDVI dominant.")
        else:
            ndvi_final_status = "AMBIGUOUS"
            ndvi_report.append("  AMBIGUOUS.")

ndvi_report.append("FINAL_STATUS: {0}".format(ndvi_final_status))
