# ============================================================================
# BEGIN PART 11   (source: PART 11.py)
# ============================================================================
# ============================================================
# PART 11: WATER QUALITY COMBINATION SENSITIVITY
# ============================================================
# Watershed Health Resilience Index (WHRI)
# ============================================================
# Purpose:
#   Test whether the WHRI ranking and Sobol sensitivity results
#   are robust to combining Surface Water Quality (SWQ) and
#   Groundwater Quality (GWQ) into a single indicator.
#
# Approach:
#   - Main analysis retains 5 indicators (SWQ, GWQ separate)
#   - Supplementary test: 4-indicator variant (WaterQuality_combined)
#   - Report rho(5-ind, 4-ind) and Sobol S1/ST comparison
#
# Output:
#   intermediate/sensitivity_wq/
#     └── wq_sensitivity_results.json
# ============================================================

import os
import json
import time
import datetime
from pathlib import Path
import numpy as np
import pandas as pd
import rasterio
from rasterio.windows import Window
from scipy.stats import spearmanr
from SALib.sample import sobol as sobol_sample
from SALib.analyze import sobol as sobol_analyze

# ============================================================
# CONFIG
# ============================================================

# Default base directory (user's Desktop)
DEFAULT_BASE = Path.home() / "Desktop"

# Config file produced by Part 1
CONFIG_PATH = str(DEFAULT_BASE / "WHRI_output" / "config" / "final_config.json")

with open(CONFIG_PATH, "r", encoding="utf-8") as f:
    CFG = json.load(f)

OUT = CFG["paths"]["output_root"]
INTERMEDIATE = os.path.join(OUT, "intermediate")
WHRI_DIR = os.path.join(INTERMEDIATE, "whri_v7")
FUZZY_DIR = os.path.join(INTERMEDIATE, "fuzzy_v7")
WEIGHTS_DIR = os.path.join(INTERMEDIATE, "weights_v7")
SOBOL_DIR = os.path.join(INTERMEDIATE, "sobol_v7")
OUT_DIR = os.path.join(INTERMEDIATE, "sensitivity_wq")
os.makedirs(OUT_DIR, exist_ok=True)

RANDOM_SEED = CFG["analysis_params"]["output"]["random_seed"]
np.random.seed(RANDOM_SEED)
SAFE_NODATA = -9999.0


def _p(msg=""):
    print(msg, flush=True)


# ============================================================
# LOAD WEIGHTS
# ============================================================

_p("\n[1/6] Loading weights ...")

with open(os.path.join(WEIGHTS_DIR, "weights_v7.json"), "r",
           encoding="utf-8") as f:
    wdata = json.load(f)

criteria_5 = wdata["criteria"]
w_5 = np.array(wdata["w_final"])
w_5 = w_5 / w_5.sum()

i_ndvi = criteria_5.index("NDVI")
i_sub = criteria_5.index("Subsidence")
i_swq = criteria_5.index("Surface WQ")
i_gwq = criteria_5.index("Groundwater WQ")
i_wd = criteria_5.index("Well Density")

w_combined_wq = w_5[i_swq] + w_5[i_gwq]
criteria_4 = ["NDVI", "Subsidence", "WaterQuality_combined", "Well Density"]
w_4 = np.array([w_5[i_ndvi], w_5[i_sub], w_combined_wq, w_5[i_wd]])
w_4 = w_4 / w_4.sum()

_p("  5-ind weights:")
for c, w in zip(criteria_5, w_5):
    _p("    {0:20s} {1:.4f}".format(c, w))
_p("  4-ind weights:")
for c, w in zip(criteria_4, w_4):
    _p("    {0:25s} {1:.4f}".format(c, w))


# ============================================================
# SAMPLE FUZZY INDICATORS + R/S AT SAME PIXELS
# ============================================================

_p("\n[2/6] Sampling fuzzy + R/S at same pixels ...")

FUZZY_PATHS_5 = {
    "NDVI":          os.path.join(FUZZY_DIR, "TBM_NDVI_Fuzzy.tif"),
    "Subsidence":    os.path.join(FUZZY_DIR,
                                   "TBM_Subsidence_Clipped_Fuzzy.tif"),
    "SurfaceWQ":     os.path.join(FUZZY_DIR,
                                   "TBM_SurfaceWaterQuality_Fuzzy.tif"),
    "GroundwaterWQ": os.path.join(FUZZY_DIR,
                                   "TBM_GroundwaterQuality_Fuzzy.tif"),
    "WellDensity":   os.path.join(FUZZY_DIR,
                                   "TBM_Well_Density_Fuzzy.tif"),
}
R_PATH = os.path.join(FUZZY_DIR, "TBM_AdaptiveCapacity.tif")
S_PATH = os.path.join(FUZZY_DIR, "TBM_StressExposure.tif")

for k, p in FUZZY_PATHS_5.items():
    if not os.path.exists(p):
        raise FileNotFoundError("Missing: {0}".format(p))
if not os.path.exists(R_PATH):
    raise FileNotFoundError("Missing R: {0}".format(R_PATH))
if not os.path.exists(S_PATH):
    raise FileNotFoundError("Missing S: {0}".format(S_PATH))

with rasterio.open(FUZZY_PATHS_5["NDVI"]) as src:
    H, W = src.height, src.width

# Open all rasters once (with proper close)
fuzzy_srcs = {k: rasterio.open(p) for k, p in FUZZY_PATHS_5.items()}
r_src = rasterio.open(R_PATH)
s_src = rasterio.open(S_PATH)

rng = np.random.default_rng(RANDOM_SEED + 1000)
collected = []
n_tries = 0
target = 2000
max_per_block = 150

try:
    while sum(len(c) for c in collected) < target and n_tries < 1500:
        n_tries += 1
        r = int(rng.integers(0, max(1, H - 64)))
        c = int(rng.integers(0, max(1, W - 64)))
        win = Window(c, r, 64, 64)

        cols = []
        ok = True
        # Read all 5 fuzzy layers
        for k, src in fuzzy_srcs.items():
            b = src.read(1, window=win).astype(np.float32)
            nd = src.nodata
            if nd is not None:
                b = np.where(b == nd, np.nan, b)
            b = np.where(b == SAFE_NODATA, np.nan, b)
            cols.append(b.ravel())
            if not np.isfinite(b).any():
                ok = False
                break
        if not ok:
            continue

        # Read R and S at SAME window
        rb = r_src.read(1, window=win).astype(np.float32)
        sb = s_src.read(1, window=win).astype(np.float32)
        if r_src.nodata is not None:
            rb = np.where(rb == r_src.nodata, np.nan, rb)
        if s_src.nodata is not None:
            sb = np.where(sb == s_src.nodata, np.nan, sb)
        rb = np.where(rb == SAFE_NODATA, np.nan, rb)
        sb = np.where(sb == SAFE_NODATA, np.nan, sb)
        rb = rb.ravel()
        sb = sb.ravel()

        stacked = np.column_stack(cols + [rb, sb])
        valid = np.all(np.isfinite(stacked), axis=1)
        if valid.sum() < 10:
            continue
        n_take = min(max_per_block, int(valid.sum()))
        idx = rng.choice(np.where(valid)[0], n_take, replace=False)
        collected.append(stacked[idx])
finally:
    for s in fuzzy_srcs.values():
        s.close()
    r_src.close()
    s_src.close()

X_all = np.vstack(collected)
if len(X_all) > 2000:
    idx = rng.choice(len(X_all), 2000, replace=False)
    X_all = X_all[idx]

_p("  Sampled {0} pixels from {1} blocks".format(
    X_all.shape[0], n_tries))

F_ndvi = X_all[:, 0]
F_sub = X_all[:, 1]
F_swq = X_all[:, 2]
F_gwq = X_all[:, 3]
F_wd = X_all[:, 4]
R_vals = X_all[:, 5]
S_vals = X_all[:, 6]

# Combined WQ
F_wq = (F_swq + F_gwq) / 2.0

# Check R/S ranges
_p("  R range: [{0:.4f}, {1:.4f}]".format(R_vals.min(), R_vals.max()))
_p("  S range: [{0:.4f}, {1:.4f}]".format(S_vals.min(), S_vals.max()))


# ============================================================
# DETERMINISTIC COMPARISON: 5-ind vs 4-ind WHRI
# ============================================================

_p("\n[3/6] Deterministic WHRI comparison ...")

base_5 = (F_ndvi * w_5[i_ndvi] + F_sub * w_5[i_sub]
          + F_swq * w_5[i_swq] + F_gwq * w_5[i_gwq]
          + F_wd * w_5[i_wd])

base_4 = (F_ndvi * w_4[0] + F_sub * w_4[1]
          + F_wq * w_4[2] + F_wd * w_4[3])

rho_diff, p_diff = spearmanr(base_5, base_4)
diff_median = float(np.median(np.abs(base_5 - base_4)))

_p("  rho(WHRI_5ind, WHRI_4ind) = {0:+.4f} (p = {1:.2e})".format(
    rho_diff, p_diff))
_p("  |difference| median = {0:.4f}".format(diff_median))

if rho_diff > 0.98:
    _p("  ✓ EXCELLENT: rankings essentially identical")
elif rho_diff > 0.95:
    _p("  ✓ VERY ROBUST: rankings highly consistent")
elif rho_diff > 0.85:
    _p("  ✓ ROBUST: rankings consistent")
else:
    _p("  [!] Rankings differ between scenarios")


# ============================================================
# SOBOL — 4-INDICATOR MODEL
# ============================================================

_p("\n[4/6] Sobol sensitivity (4-indicator model) ...")

with open(os.path.join(WHRI_DIR, "calibration_v7.json"), "r",
           encoding="utf-8") as f:
    calib = json.load(f)
lambda_0 = calib["lambda_final"]
nu_0 = calib["nu_final"]
_p("  lambda_0 = {0:.3f}, nu_0 = {1:.3f}".format(lambda_0, nu_0))

PERTURB_W = 0.20
PERTURB_F = 0.15
PERTURB_MOD = 0.20

# 10 variables: 4 weights + 4 fuzzy + lambda + nu
problem = {
    "num_vars": 10,
    "names": ["W_NDVI", "W_Subsidence", "W_WQcombined", "W_WellDensity",
              "F_NDVI", "F_Subsidence", "F_WQcombined", "F_WellDensity",
              "lambda_R", "nu_S"],
    "bounds": (
        [[-PERTURB_W, PERTURB_W]] * 4
        + [[-PERTURB_F, PERTURB_F]] * 4
        + [[-PERTURB_MOD, PERTURB_MOD]]
        + [[-PERTURB_MOD, PERTURB_MOD]]
    ),
}

N_SOBOL = 1024
X_sobol = sobol_sample.sample(problem, N_SOBOL,
                                calc_second_order=True,
                                seed=RANDOM_SEED)
n_samples = X_sobol.shape[0]
_p("  Samples: {0}".format(X_sobol.shape))

F_full = np.column_stack([F_ndvi, F_sub, F_wq, F_wd])

mean_whri = np.zeros(n_samples, dtype=np.float32)
BATCH = 1000
n_batches = (n_samples + BATCH - 1) // BATCH
t0 = time.time()

for bi in range(n_batches):
    s0 = bi * BATCH
    s1 = min(s0 + BATCH, n_samples)
    Xb = X_sobol[s0:s1]

    dw = Xb[:, 0:4]
    W_pert = w_4[None, :] * (1.0 + dw)
    W_pert = np.maximum(W_pert, 1e-6)
    W_norm = W_pert / W_pert.sum(axis=1, keepdims=True)

    F_pert = F_full[None, :, :] * (1.0 + Xb[:, None, 4:8])
    F_pert = np.clip(F_pert, 0.0, 1.0)

    base = np.einsum("bk,bnk->bn", W_norm, F_pert)

    lam = np.maximum(lambda_0 * (1.0 + Xb[:, 8]), 0.0)
    nu = np.maximum(nu_0 * (1.0 + Xb[:, 9]), 0.0)
    factor = ((1.0 + lam[:, None] * R_vals[None, :])
              * (1.0 - nu[:, None] * S_vals[None, :]))
    whri = base * factor

    mean_whri[s0:s1] = whri.mean(axis=1)

    if (bi + 1) % 5 == 0:
        _p("    batch {0}/{1}  ({2:.1f}s)".format(
            bi + 1, n_batches, time.time() - t0))

Si = sobol_analyze.analyze(problem, mean_whri,
                             calc_second_order=True,
                             print_to_console=False,
                             seed=RANDOM_SEED)
S1_4 = np.array(Si["S1"])
ST_4 = np.array(Si["ST"])
S1c_4 = np.array(Si["S1_conf"])
STc_4 = np.array(Si["ST_conf"])

_p("\n  Sobol S1/ST (4-indicator model):")
for name, s1, st in zip(problem["names"], S1_4, ST_4):
    _p("    {0:22s} S1={1:+.4f}  ST={2:+.4f}".format(name, s1, st))


# ============================================================
# COMPARE WITH 5-INDICATOR SOBOL
# ============================================================

_p("\n[5/6] Comparison with 5-indicator Sobol ...")

sobol_5_file = os.path.join(SOBOL_DIR, "sobol_results_v7.json")
comparison = {}

if os.path.exists(sobol_5_file):
    with open(sobol_5_file, "r", encoding="utf-8") as f:
        sobol_5 = json.load(f)

    S1_5 = np.array(sobol_5["output_mean_WHRI"]["S1"])
    ST_5 = np.array(sobol_5["output_mean_WHRI"]["ST"])
    names_5 = sobol_5["meta"]["variable_names"]

    i_swq5 = names_5.index("F_SurfaceWQ")
    i_gwq5 = names_5.index("F_GroundwaterWQ")

    # 5-ind: aggregate WQ contribution
    S1_5_wq_sum = float(S1_5[i_swq5] + S1_5[i_gwq5])
    ST_5_wq_sum = float(ST_5[i_swq5] + ST_5[i_gwq5])

    # 4-ind: single combined WQ
    i_wq4 = problem["names"].index("F_WQcombined")
    S1_4_wq = float(S1_4[i_wq4])
    ST_4_wq = float(ST_4[i_wq4])

    comparison = {
        "S1_wq_5ind_sum": S1_5_wq_sum,
        "S1_wq_4ind": S1_4_wq,
        "ST_wq_5ind_sum": ST_5_wq_sum,
        "ST_wq_4ind": ST_4_wq,
        "S1_ratio": S1_4_wq / S1_5_wq_sum if S1_5_wq_sum else np.nan,
        "ST_ratio": ST_4_wq / ST_5_wq_sum if ST_5_wq_sum else np.nan,
    }

    _p("  WQ contribution comparison:")
    _p("    5-ind model (S1 SWQ + S1 GWQ) = {0:.4f}".format(S1_5_wq_sum))
    _p("    4-ind model (S1 WQcombined)   = {0:.4f}".format(S1_4_wq))
    _p("    Ratio (S1)                    = {0:.3f}".format(
        comparison["S1_ratio"]))
    _p("    5-ind model (ST SWQ + ST GWQ) = {0:.4f}".format(ST_5_wq_sum))
    _p("    4-ind model (ST WQcombined)   = {0:.4f}".format(ST_4_wq))
    _p("    Ratio (ST)                    = {0:.3f}".format(
        comparison["ST_ratio"]))

    # Additional context: sum of S1 across all variables
    _p("  Sum S1:")
    _p("    5-ind model: {0:.4f}".format(np.sum(S1_5)))
    _p("    4-ind model: {0:.4f}".format(np.sum(S1_4)))

    # Interpret
    if abs(comparison["S1_ratio"] - 1.0) < 0.15:
        _p("  ✓ WQ contribution is consistent between models")
    else:
        _p("  [!] WQ contribution differs — investigate")


# ============================================================
# SAVE RESULTS
# ============================================================

_p("\n[6/6] Saving results ...")

results = {
    "meta": {
        "generated": datetime.datetime.now().isoformat(),
        "purpose": "Sensitivity to combining SWQ + GWQ into one indicator",
        "n_pixels": int(X_all.shape[0]),
        "N_sobol": int(N_SOBOL),
        "n_variables_4ind": 10,
        "random_seed": int(RANDOM_SEED),
        "perturbations": {
            "weights": float(PERTURB_W),
            "fuzzy_values": float(PERTURB_F),
            "modifiers": float(PERTURB_MOD),
        },
    },
    "deterministic_comparison": {
        "rho_5ind_vs_4ind": float(rho_diff),
        "p_value": float(p_diff),
        "abs_diff_median": float(diff_median),
    },
    "sobol_4ind": {
        "names": problem["names"],
        "S1": [float(x) for x in S1_4],
        "S1_conf": [float(x) for x in S1c_4],
        "ST": [float(x) for x in ST_4],
        "ST_conf": [float(x) for x in STc_4],
    },
    "wq_contribution_comparison": comparison,
    "recommendation": (
        "Retain 5 indicators in the main analysis. Report this "
        "4-indicator variant as a supplementary robustness check. "
        "The WHRI ranking is robust to this choice "
        "(rho = {0:.4f}).".format(rho_diff)
    ),
}

out_json = os.path.join(OUT_DIR, "wq_sensitivity_results.json")
with open(out_json, "w", encoding="utf-8") as f:
    json.dump(results, f, ensure_ascii=False, indent=2, default=str)

_p("  Saved: {0}".format(out_json))


# ============================================================
# FINAL SUMMARY
# ============================================================

_p("\n" + "=" * 88)
_p(" PART 11 COMPLETE")
_p("=" * 88)
_p("  rho(5ind vs 4ind)          : {0:+.4f}".format(rho_diff))
_p("  |diff| median              : {0:.4f}".format(diff_median))
if comparison:
    _p("  S1_WQ (5-ind sum)          : {0:.4f}".format(
        comparison["S1_wq_5ind_sum"]))
    _p("  S1_WQ (4-ind)              : {0:.4f}".format(
        comparison["S1_wq_4ind"]))
    _p("  ST_WQ (5-ind sum)          : {0:.4f}".format(
        comparison["ST_wq_5ind_sum"]))
    _p("  ST_WQ (4-ind)              : {0:.4f}".format(
        comparison["ST_wq_4ind"]))
_p()
_p("  Output: {0}".format(out_json))
_p("=" * 88)

